INSERT INTO `tbl_campus` (`id`, `type_id`, `staff_id`, `title`, `subtitle`, `description`, `image`, `date`, `is_active`, `is_delete`, `create_at`, `update_at`, `create_by`, `update_by`) VALUES
(1, 2, 0, 'FACULTY DEVELOPMENT PROGRAM', '', '<p>The Faculty Development Program(FDP) is specially for faculty members of institutes. The FDP has been designed and continuously re-structured to address emerging developmental and needs of technical educators. The Program simply aims at developing the pedagogical skills of the participants. FDP is compulsory for all faculties enhance teaching capabilities at GMIU.</p>\r\n', '', '0000-00-00', 0, 1, '2024-04-06 04:40:36', '0000-00-00 00:00:00', NULL, NULL),
(2, 1, 0, '', '', '<p><strong>N/A</strong></p>\r\n', '', '2019-02-07', 1, 0, '2024-03-26 08:43:44', '0000-00-00 00:00:00', NULL, NULL),
(3, 3, 0, 'PARENTS COUNSELLING SESSIONS', '', '<p>Regular parents meetings have been arranged at college to discuss student&#39;s progress. A parent-teacher meeting is a short meeting or conference between the parents and teachers of students to convey resport cards by focusing on student&#39;s specific strengths and weaknesses in individual subjects and generalizing the level of intercurricular skills and competencies.</p>\r\n\r\n<p>Parents meetings are actually a series of sessions which have been executed to make parents aware about their role in higher education and how they can help their child to be a successful engineer as well as how to face competitive professional environment.</p>\r\n', '', '0000-00-00', 1, 0, '2024-03-26 08:51:17', '0000-00-00 00:00:00', NULL, NULL),
(4, 1, 0, '', '', '<p><strong>N/A</strong></p>\r\n', '', '2018-02-15', 0, 1, '2024-04-02 11:02:36', '0000-00-00 00:00:00', NULL, NULL),
(5, 1, 0, '', '', '<p><strong>N/A</strong></p>\r\n', '', '2017-02-23', 1, 0, '2024-03-26 10:13:12', '0000-00-00 00:00:00', NULL, NULL),
(6, 1, 0, '', '', '', '', '2017-02-14', 0, 1, '2024-03-26 10:12:44', '0000-00-00 00:00:00', NULL, NULL),
(7, 2, 0, 'FACULTY DEVELOPMENT PROGRAM', '', '<p>The Faculty Development Program(FDP) is specially for faculty members of institutes. The FDP has been designed and continuously re-structured to address emerging developmental and needs of technical educators. The Program simply aims at developing the pedagogical skills of the participants. FDP is compulsory for all faculties enhance teaching capabilities at GMIU.</p>\r\n', '', '0000-00-00', 1, 0, '2024-04-06 04:42:14', '0000-00-00 00:00:00', NULL, NULL),
(8, 10, 0, 'CIVIL LABORATORY', '', '<p>We have very good equipped laboratories with letest machines available in our laboratories for students to work with so that student can experience industry in the college.</p>\r\n', '', '0000-00-00', 1, 0, '2024-04-22 06:13:05', '0000-00-00 00:00:00', NULL, NULL),
(9, 10, 0, 'COMPUTER/IT LAB', '', '<p>We have fully developed computer with high configuration pcs installed with needed software for students to use. All PCs are connected with internet connections.</p>\r\n', '', '0000-00-00', 1, 0, '2024-04-22 06:13:42', '0000-00-00 00:00:00', NULL, NULL),
(10, 10, 0, 'ELECTRICAL LAB', '', '<p>Electrical laboratories contains all the devices that is needed to run practical and laboratories having safety kit available in it.</p>\r\n', '', '0000-00-00', 1, 0, '2024-04-22 06:14:08', '0000-00-00 00:00:00', NULL, NULL),
(11, 10, 0, 'MECHANICAL LAB', '', '<p>Mechanical laboratories with letest machinaries are 24*7 available to students to learn mechanical skills.</p>\r\n', '', '0000-00-00', 1, 0, '2024-04-22 06:14:38', '0000-00-00 00:00:00', NULL, NULL),
(12, 5, 0, '2016', '', '', '', '0000-00-00', 1, 0, '2024-04-22 06:24:08', '0000-00-00 00:00:00', NULL, NULL),
(13, 5, 0, ' Enjinia 17', '', '', '', '0000-00-00', 1, 0, '2025-06-26 09:51:43', '0000-00-00 00:00:00', NULL, NULL),
(14, 5, 0, ' Sustainable Energy Project Exhibition ', '', '', '', '0000-00-00', 1, 0, '2024-04-22 06:26:13', '0000-00-00 00:00:00', NULL, NULL),
(15, 5, 0, ' Techmanjari 2020 ', '', '', '', '0000-00-00', 1, 0, '2024-04-22 06:27:01', '0000-00-00 00:00:00', NULL, NULL),
(16, 4, 22, ' Center For Higher Studies ', 'HIGHER STUDIES - ABROAD', '<ul>\r\n	<li>All Information regarding Higher Studies (IIT,IIM,NIT,IISC etc)</li>\r\n	<li>Eligibility Criteria &amp; Admission Procedure</li>\r\n	<li>Scope after Higher Studies</li>\r\n	<li>Qualifying Examination(GATE,CAT etc.)</li>\r\n	<li>Financial Requirement</li>\r\n	<li>Scholership &amp; Education Loan</li>\r\n	<li>Integrated Programs</li>\r\n</ul>\r\n', '', '0000-00-00', 1, 0, '2024-04-22 06:40:59', '0000-00-00 00:00:00', NULL, NULL),
(17, 4, 11, ' Placement Cell ', 'MNC/PSU/TOP COMPANIES', '<ul>\r\n	<li>The objective of this avenue is to develop boundary-crossing skills and prepare them in such a way that they can end-up their engineering journey with offer letter from reputed MNCs.</li>\r\n</ul>\r\n', '', '0000-00-00', 1, 0, '2024-04-22 06:39:44', '0000-00-00 00:00:00', NULL, NULL),
(18, 4, 15, ' Placement Cell ', 'GOVERNMENT SECTOR/CIVIL SERVICES', '<ul>\r\n	<li>Know Latest Openings</li>\r\n	<li>Preparation &amp; Practice</li>\r\n	<li>Checking the first stage - Written Exam</li>\r\n	<li>Preliminary Examination</li>\r\n	<li>Application Procedure</li>\r\n	<li>Eligibility Criteria</li>\r\n	<li>Expertise in Core Subjects as well as GK</li>\r\n	<li>Aptitude</li>\r\n</ul>\r\n', '', '0000-00-00', 1, 0, '2024-04-22 06:42:13', '0000-00-00 00:00:00', NULL, NULL),
(19, 1, 0, '', '', '<p>Volley Ball Tournament organized at GMIU</p>\r\n', '', '2024-09-04', 1, 0, '2024-12-17 08:54:58', '0000-00-00 00:00:00', NULL, NULL),
(20, 1, 0, '', '', '<p>Celebrating Champions and Team Spirit</p>\r\n', '', '2024-09-05', 1, 0, '2024-12-17 08:56:14', '0000-00-00 00:00:00', NULL, NULL),
(21, 11, 0, '', '', '<p><strong>N/A</strong></p>\r\n', '', '2024-09-05', 0, 1, '2024-09-11 09:31:08', '0000-00-00 00:00:00', NULL, NULL);
