(207, 1, '5', '25', '2024-02-23', '2024', 'Indian Space Research Organiza', '<p>The Department of Computer Science and Engineering Students visited the <strong>Indian Space Research Organization (ISRO)</strong> on <strong>23rd February 2024</strong>.</p>\r\n\r\n<p>&nbsp;</p>\r\n', '2024-07-20-85-2nd Diploma - B.pdf', 1, 0, '2024-12-20 07:26:19', '2024-12-20 07:26:19', NULL, NULL),
(208, 1, '1', '4', '2024-03-05', '2024', 'ISRO Ahmadabad', '<p style=\"margin-left:8px; margin-right:4px; text-align:justify\">The Department of Computer Science and Engineering students of Class A&nbsp; visited ISRO, Ahemdabad on 5th March, 2024.</p>\r\n', '2024-07-20-61-2nd Degree A Isro.pdf', 1, 0, '2024-12-19 11:26:25', '2024-12-19 11:26:25', NULL, NULL),
(209, 1, '1', '4', '2024-03-06', '2024', 'ISRO Ahmadabad', '<p style=\"margin-left:8px; margin-right:4px; text-align:justify\">The Department of Computer Science and Engineering students of Class B visited ISRO, Ahemdabad on 6th March, 2024.</p>\r\n', '2024-07-20-29-2nd Degree B Isro.pdf', 1, 0, '2024-12-19 11:27:04', '2024-12-19 11:27:04', NULL, NULL),
(210, 1, '5', '25', '2024-02-21', '2024', 'BISAG, Gandhinagar', '<p style=\"margin-left:41px; margin-right:33px; text-align:justify\"><span style=\"font-size:14pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><strong>Bhaskaracharya Institute for Space Applications and Geo-informatics </strong>(BISAG) is a state level agency by Government of Gujarat to facilitate to provid eservices and solutions in implementing map-basedGeo-Spatial Information Systems. BISAG&#39;s SATCOM network is a satellite communication network serviceto provide distant interaction statewide. Currently BISAG is working to implementgeo-spatial technologies for the planning and developmental activities pertaining to agriculture, land and water resource management, wasteland/ water shed development, forestry, disaster management, infrastructure and education.</span></span></p>\r\n', '2024-07-20-42-4th Diploma Normal Bisag (1).pdf', 0, 1, '2024-12-27 04:47:42', '2024-12-27 04:47:42', NULL, NULL),
(211, 1, '5', '25', '2024-02-20', '2024', 'BISAG, Gandhinagar', '<p style=\"margin-left:41px; margin-right:33px; text-align:justify\"><span style=\"font-size:14pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><strong>Bhaskaracharya Institute for Space Applications and Geo-informatics </strong>(BISAG) is a state level agency by Government of Gujarat to facilitate to provid eservices and solutions in implementing map-basedGeo-Spatial Information Systems. BISAG&#39;s SATCOM network is a satellite communication network serviceto provide distant interaction statewide. Currently BISAG is working to implementgeo-spatial technologies for the planning and developmental activities pertaining to agriculture, land and water resource management, wasteland/ water shed development, forestry, disaster management, infrastructure and education.</span></span></p>\r\n', '2024-07-20-88-4th DiplomaGenius Bisag.pdf', 0, 1, '2024-12-27 04:47:51', '2024-12-27 04:47:51', NULL, NULL),
(212, 1, '1', '4', '2024-03-29', '2024', 'Odoo India  (Tiny ERP Pvt. Ltd', '<p style=\"margin-left:21px; text-align:justify\">The Department of Computer Science and Engineering students&nbsp; visited ISRO, Ahemdabad on 29th March, 2024.</p>\r\n', '2024-07-20-37-6th Degree Odoo.pdf', 1, 0, '2024-12-19 11:32:41', '2024-12-19 11:32:41', NULL, NULL),
(213, 1, '5', '23', '2024-07-23', '2024', 'Industry Visit At Amul Dairy  ', '<p><span style=\"font-size:14px\">A visit to Amul Anand for diploma IT engineering students provides insight into dairy processing, automation, and IT infrastructure, showcasing real-world applications of their studies in a leading industry.</span></p>\r\n', '2024-08-01-32-industrial visit .pdf', 1, 0, '2024-08-02 07:48:01', '2024-08-02 07:48:01', NULL, NULL),
