(123, '', 0, 3, 1, 'B.Sc Physics Hon. In Radiotherapy', 'under-graduation-b-sc-physics-hon-in-radiotherapy', '', '<p style=\"text-align:justify\"><span style=\"font-size:16px\">B.Sc. Radiotherapy technology is a 4-year graduation program. Radiotherapy, also called radiation therapy, is the treatment of cancer and other diseases with ionizing radiation. This program is designed to provide students with in-depth knowledge of the principles and practice of radiotherapy, including the use of radiation in the treatment of cancer, radiation physics, radiation biology, treatment planning, and patient care.</span></p>\r\n', '', '', '', '', 'N/A', 'N/A', '3', 30, '4', 59500, 33650, 31250, 31600, 31250, 31600, 31250, 31600, 34250, 0, 0, 0, 0, 6000, 6000, 0, 0, 0, 0, 0, 0, '', '', 0, 0, '2023-03-14 09:39:27', '2025-06-09 04:38:06', 0, 0),
(124, '', 0, 3, 2, 'Medical Techology', 'post-graduation-medical-techology', '', '', '', '', '', '', '', '', '3', 60, '2', 50400, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 5000, 6000, 0, 0, 0, 0, 0, 0, '', '', 0, 1, '2023-03-14 09:41:48', '2025-06-09 04:38:06', 0, 0),
(125, '', 0, 3, 2, 'M.sc. Radiotherapy', 'post-graduation-m-sc-radiotherapy', '', '<p style=\"text-align:justify\"><span style=\"font-size:16px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">A Master of Science (M.Sc) in Radiotherapy program provides students with the knowledge, skills, and clinical experience needed to pursue careers as radiation therapists in healthcare settings specializing in cancer treatment. Graduates play a vital role in the multidisciplinary team approach to cancer care, contributing to the delivery of safe, effective, and compassionate radiation therapy services to patients.</span></span></p>\r\n', '', '', '', '', 'N/A', 'N/A', '3', 30, '2', 66400, 37550, 34900, 35250, 37900, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 10000, 6000, 0, 0, 0, 0, 0, 0, '', '', 0, 0, '2023-03-14 09:41:48', '2025-06-09 04:38:06', 0, 0),
(126, 'G78', 0, 4, 1, 'B.com Honor In Innovation &amp; Startup', 'under-graduation-b-com-honor-in-innovation-amp-startup', 'Commerce study is one of the most popular courses among Graduates and post graduate. Those who want to gain in-depth knowledge in commerce stream can study B.Com and M.Com. Commerce courses are designed to provide knowledge in specific subjects. A typical Commerce course in the Field of Commerce focuses on an overview of all subjects under the umbrella of the Commerce stream. A large proportion of students who passed in class 12th with B.Com commerce stream are aspiring for chartered accountancy, company secretary ship and cost accounting. After completing the Commerce course, one can go for further courses in Teaching, Advertising, Journalism, Mass Communication, Design, Law etc. In B.Com there are current demand based courses like Finance and Accounting , Banking and Insurance, Marketing and Management. Now more students can join this the course.', '<p style=\"text-align:justify\"><span style=\"font-size:16px\">Commerce study is one of the most popular courses among Graduates and post graduate. Those who want to gain in-depth knowledge in commerce stream can study B.Com and M.Com. Commerce courses are designed to provide knowledge in specific subjects. A typical Commerce course in the Field of Commerce focuses on an overview of all subjects under the umbrella of the Commerce stream. A large proportion of students who passed in class 12th with B.Com commerce stream are aspiring for chartered accountancy, company secretary ship and cost accounting. After completing the Commerce course, one can go for further courses in Teaching, Advertising, Journalism, Mass Communication, Design, Law etc. In B.Com there are current demand based courses like Finance and Accounting , Banking and Insurance, Marketing and Management. Now more students can join this the course.</span></p>\r\n', 'Develop business ideas and entrepreneurial skills with our B.Com in Innovation & Startup program. Learn finance, marketing, and startup management.', 'B.Com innovation, entrepreneurship degree, startup business course, B.Com Hons, UG commerce innovation, startup education, business innovation UG', '', 'B.Com (Hons) in Innovation & Startup – Institute of Commerce', 'N/A', 'N/A', '4', 60, '4', 52300, 28550, 26150, 26500, 26150, 26500, 26150, 26500, 29150, 0, 42800, 42800, 0, 6000, 6000, 0, 0, 0, 0, 0, 0, '', '', 1, 0, '2023-03-14 10:05:48', '2025-06-18 12:05:19', 0, 0),
(127, 'G98', 1, 5, 1, 'BBA Hon. Innovation &amp; Entrepreneurship (PREMIUM)', 'under-graduation-bba-hon-innovation-amp-entrepreneurship-premium', '', '<p style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"font-size:16px\"><span style=\"background-color:white\"><span style=\"color:#212529\">A graduate degree in business administration is awarded to candidates who successfully complete GMIU&#39;s three-year, full-time business administration curriculum (BBA). This programme is highly esteemed and considered to be among the best of its kind in the nation.</span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"font-size:16px\"><span style=\"background-color:white\"><span style=\"color:#212529\">A conceptual and analytical understanding of Indian and global business is established via the curriculum. The BBA programme at GMIU is meant to incorporate modern management theory and practise in a seamless manner. The course offers knowledge and cultivates attitudes that are crucial for students&#39; development into capable, accountable managers. The curriculum content for the course is continually updated to reflect the most recent developments.</span></span></span></span></p>\r\n', 'Launch your entrepreneurial journey with our premium BBA course. Learn business models, startup financing, innovation strategy, and leadership.', 'BBA innovation, entrepreneurship premium BBA, startup leadership, BBA entrepreneurship, UG business innovation, business management Gujarat', '', 'BBA (Hons) in Innovation & Entrepreneurship – Premium Program – Institute of Management', 'N/A', 'BBA Hon. IE (PREMIUM)', '5', 30, '4', 79000, 41900, 39500, 39850, 39500, 39850, 39500, 39850, 42500, 0, 69500, 0, 0, 6000, 6000, 0, 0, 0, 0, 0, 0, '', '', 1, 0, '2023-03-14 10:17:14', '2025-08-05 09:38:33', 0, 0),
