(616, '', 1, 5, 1, 'BBA Hon. Innovation &amp; Entrepreneurship', 'under-graduation-bba-hon-innovation-amp-entrepreneurship', '', '<p style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"font-size:16px\">A graduate degree in business administration is awarded to candidates who successfully complete GMIU&#39;s three-year, full-time business administration curriculum (BBA). This programme is highly esteemed and considered to be among the best of its kind in the nation.</span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif\"><span style=\"font-size:16px\">A conceptual and analytical understanding of Indian and global business is established via the curriculum. The BBA programme at GMIU is meant to incorporate modern management theory and practise in a seamless manner. The course offers knowledge and cultivates attitudes that are crucial for students&#39; development into capable, accountable managers. The curriculum content for the course is continually updated to reflect the most recent developments.</span></span></p>\r\n\r\n<p>&nbsp;</p>\r\n', '', '', '', '', '', 'BBA Hon. IE', '', 30, '4', 79000, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 6000, 0, 0, 0, NULL, NULL, NULL, '', '', 1, 0, '2025-08-05 09:15:14', '2025-08-05 09:38:15', NULL, NULL),
(617, '', 0, 3, 1, 'B.Sc Micro Hon in. Clinical Embryology', 'under-graduation-b-sc-micro-hon-in-clinical-embryology', '', '<p style=\"text-align:justify\"><span style=\"font-size:16px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">A Bachelor of Science (BSc) in Microbiology with Honors in&nbsp; Clinical Embryology typically focuses on the study of microorganisms and their interactions, with a specialized emphasis on embryonic development. This program often includes courses covering microbiological principles, genetics, cell biology, and specialized topics related to embryology, such as developmental biology and reproductive biology. Students may engage in laboratory work, gaining practical skills in microbiological techniques and embryological research. The honors component may involve in-depth research projects or additional coursework, providing a more comprehensive understanding of both microbiology and embryology.</span></span></p>\r\n', '', '', '', '', '', '', '', 30, '4', 79000, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 6000, 0, 0, 0, NULL, NULL, NULL, '', '', 1, 0, '2025-08-05 10:11:17', '2025-08-05 10:11:17', NULL, NULL),
(618, '', 0, 3, 2, 'M.Sc  Clinical Embryology', 'post-graduation-m-sc-clinical-embryology', '', '<p><span style=\"font-size:16px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">M.Sc in Embryology program provides students with advanced theoretical knowledge, practical skills, and research experience in the field of embryonic development, preparing them for careers in research institutions, academia, clinical laboratories, biotechnology companies, pharmaceutical industries, and other related fields. Graduates may work as embryologists, research scientists, laboratory technicians, educators.</span></span></p>\r\n', '', '', '', '', '', '', '', 30, '2', 142000, 73650, 71000, 71350, 74000, 0, 0, 0, 0, NULL, NULL, NULL, 0, NULL, 6000, 0, 0, 0, NULL, NULL, NULL, '', '', 1, 0, '2025-08-05 10:58:06', '2025-10-15 08:12:10', NULL, NULL),
(619, '', 0, 3, 2, 'M.Sc  Clinical Embryology', 'post-graduation-m-sc-clinical-embryology', '', '<p><span style=\"font-size:16px\"><span style=\"font-family:Arial,Helvetica,sans-serif\">M.Sc in Embryology program provides students with advanced theoretical knowledge, practical skills, and research experience in the field of embryonic development, preparing them for careers in research institutions, academia, clinical laboratories, biotechnology companies, pharmaceutical industries, and other related fields. Graduates may work as embryologists, research scientists, laboratory technicians, educators.</span></span></p>\r\n', '', '', '', '', '', '', '', 30, '2', 142000, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 6000, 0, 0, 0, NULL, NULL, NULL, '', '', 0, 0, '2025-08-05 10:58:06', '2025-08-05 10:59:38', NULL, NULL),
