(21, 1, 1, 1, 'PO 8: Ethics', '<p><span style=\"font-size:18px\"><span style=\"font-family:Times New Roman,Times,serif\">Apply ethical principles and commit to professional ethics and responsibilities and norms of the engineering practice</span></span></p>\r\n', 1, 0, '2023-10-05 14:22:47', '2023-10-05 14:22:47', NULL, NULL),
(22, 1, 1, 1, 'PO 9: Individual &amp; teamwork', '<p><span style=\"font-size:18px\"><span style=\"font-family:Times New Roman,Times,serif\">Function effectively as an individual, and as a member of leader in diverse terms, and in multidisciplinary settings</span></span></p>\r\n', 1, 0, '2023-10-05 14:23:55', '2023-10-05 14:23:55', NULL, NULL),
(23, 1, 1, 1, 'PO 10: Communication', '<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:18px\">Communicate effectively on complex engineering activities with the engineering community and society at large by comprehending and writing effective reports and design documentation, making effective presentations, and giving and receiving clear instructions.</span></span></p>\r\n', 1, 0, '2023-10-05 14:25:00', '2023-10-05 14:25:00', NULL, NULL),
(24, 1, 1, 1, 'PO 11: Project Management &amp; Finance', '<p><span style=\"font-size:18px\"><span style=\"font-family:Times New Roman,Times,serif\">Demonstrate knowledge and understanding of the engineering and management principles and apply these to one&rsquo;s work, as a number and leader in term, to manage projects and in multidisciplinary environments</span></span></p>\r\n', 1, 0, '2023-10-05 14:25:55', '2023-10-05 14:25:55', NULL, NULL),
(25, 1, 1, 1, 'PO 12: Life-long learning', '<p><span style=\"font-size:18px\"><span style=\"font-family:Times New Roman,Times,serif\">Recognize the need for, and have the preparation and ability to engage in independent and life-long learning in the broadest context of technological change</span></span></p>\r\n', 1, 0, '2023-10-05 14:26:43', '2023-10-05 14:26:43', NULL, NULL),
(26, 8, 1, 89, 'Problem analysis', '<p>Identify, formulate, review research literature, and analyze complex engineering problems reaching substantiated conclusions using first principles of mathematics, natural sciences, and engineering sciences.</p>\r\n', 1, 0, '2023-10-06 05:31:15', '2023-10-06 05:31:15', NULL, NULL),
(27, 8, 1, 89, 'Design/development of solutions', '<p>Design solutions for complex engineering problems and design system components or processes that meet the specified needs with appropriate consideration for the public health and safety, and the cultural, societal, and environmental considerations.</p>\r\n', 1, 0, '2023-10-06 05:32:24', '2023-10-06 05:32:24', NULL, NULL),
(28, 8, 1, 89, 'Conduct investigations of complex problems', '<p>Use research-based knowledge and research methods including design of experiments, analysis and interpretation of data, and synthesis of the information to provide valid conclusions.</p>\r\n', 1, 0, '2023-10-06 05:32:45', '2023-10-06 05:32:45', NULL, NULL),
(29, 8, 1, 89, 'Environment And Sustainability', '<p>Understand the impact of the professional engineering solutions in societal and environmental contexts, and demonstrate the knowledge of, and need for sustainable development.</p>\r\n', 1, 0, '2023-10-06 05:33:18', '2023-10-06 05:33:18', NULL, NULL),
(30, 8, 1, 89, 'Ethics', '<p>Apply ethical principles and commit to professional ethics and responsibilities and norms of the engineering practice.</p>\r\n', 1, 0, '2023-10-06 05:33:39', '2023-10-06 05:33:39', NULL, NULL),
(31, 8, 1, 89, 'Individual and team work', '<p>Function effectively as an individual, and as a member or leader in diverse teams, and in multidisciplinary settings.</p>\r\n', 1, 0, '2023-10-06 05:34:10', '2023-10-06 05:34:10', NULL, NULL),
(32, 8, 1, 89, 'Communication', '<p>Communicate effectively on complex engineering activities with the engineering community and with society at large, such as, being able to comprehend and write effective reports and design documentation, make effective presentations, and give and receive clear instructions.</p>\r\n', 1, 0, '2023-10-06 05:34:36', '2023-10-06 05:34:36', NULL, NULL),
(33, 8, 1, 89, 'Project management and finance', '<p>Demonstrate knowledge and understanding of the engineering andmanagement principles and apply these to own work, as a member and leader in a team, to manage projects and in multidisciplinary environments.</p>\r\n', 1, 0, '2023-10-06 05:35:07', '2023-10-06 05:35:07', NULL, NULL),
(34, 8, 1, 89, 'Life-long learning', '<p>Recognize the need for, and have the preparation and ability to engage in independent and life-long learning in the broadest context of technological change.</p>\r\n', 1, 0, '2023-10-06 05:36:42', '2023-10-06 05:36:42', NULL, NULL),
(35, 1, 1, 4, 'demo', '<p>demo</p>\r\n', 1, 1, '2023-10-06 09:18:25', '2023-10-06 09:18:25', NULL, NULL),
(36, 1, 5, 24, 'Program outcome', '<ul>\r\n	<li style=\"list-style-type:disc\"><span style=\"font-size:13.999999999999998pt\"><span style=\"font-family:\'Times New Roman\',serif\"><span style=\"color:#000000\">Diploma engineers will be able to demonstrate knowledge of electrical and electronics engineering.</span></span></span></li>\r\n	<li style=\"list-style-type:disc\"><span style=\"font-size:13.999999999999998pt\"><span style=\"font-family:\'Times New Roman\',serif\"><span style=\"color:#000000\">Ability to recognize the need and to engage in independent and life-long learning.</span></span></span></li>\r\n	<li style=\"list-style-type:disc\"><span style=\"font-size:13.999999999999998pt\"><span style=\"font-family:\'Times New Roman\',serif\"><span style=\"color:#000000\">Ability to apply the principles of management to one&#39;s own work, as a member and leader in a team, to manage project.</span></span></span></li>\r\n	<li style=\"list-style-type:disc\"><span style=\"font-size:13.999999999999998pt\"><span style=\"font-family:\'Times New Roman\',serif\"><span style=\"color:#000000\">&nbsp;Diploma engineers will demonstrate an ability to identify, formulate and solve Industrial, community &amp; research problems.&nbsp;</span></span></span></li>\r\n	<li style=\"list-style-type:disc\"><span style=\"font-size:13.999999999999998pt\"><span style=\"font-family:\'Times New Roman\',serif\"><span style=\"color:#000000\">. Diploma engineers will demonstrate an ability to analyze and interpret experiments for mathematical modeling and maintenance of the electrical systems.</span></span></span></li>\r\n	<li style=\"list-style-type:disc\"><span style=\"font-size:13.999999999999998pt\"><span style=\"font-family:\'Times New Roman\',serif\"><span style=\"color:#000000\">Diploma engineers to Design &amp; Conduct Experiments, as well as Analyze &amp; Interpret Data.&nbsp;</span></span></span></li>\r\n	<li style=\"list-style-type:disc\"><span style=\"font-size:13.999999999999998pt\"><span style=\"font-family:\'Times New Roman\',serif\"><span style=\"color:#000000\">&nbsp;Diploma engineers ability to design a System, Component, or Process to meet desired needs with in realistic constraints such as Economic, Environmental, Social, Ethical, Manufacturability, and Sustainability.</span></span></span></li>\r\n	<li style=\"list-style-type:disc\"><span style=\"font-size:13.999999999999998pt\"><span style=\"font-family:\'Times New Roman\',serif\"><span style=\"color:#000000\">&nbsp;Diploma engineers will demonstrate skills to use modern devices, software and equipment to analyse&amp; solve problems.&nbsp;</span></span></span></li>\r\n	<li style=\"list-style-type:disc\"><span style=\"font-size:13.999999999999998pt\"><span style=\"font-family:\'Times New Roman\',serif\"><span style=\"color:#000000\">&nbsp;Diploma engineers an understanding of Professional and Ethical responsibility.&nbsp;</span></span></span></li>\r\n	<li style=\"list-style-type:disc\"><span style=\"font-size:13.999999999999998pt\"><span style=\"font-family:\'Times New Roman\',serif\"><span style=\"color:#000000\">&nbsp;Diploma engineers will be able to communicate effectively both verbally and in writing.&nbsp;</span></span></span></li>\r\n	<li style=\"list-style-type:disc\"><span style=\"font-size:13.999999999999998pt\"><span style=\"font-family:\'Times New Roman\',serif\"><span style=\"color:#000000\">&nbsp;Diploma engineers will be able to understand impact of Electrical engineering on the societal and contemporary issues.</span></span></span></li>\r\n	<li style=\"list-style-type:disc\"><span style=\"font-size:13.999999999999998pt\"><span style=\"font-family:\'Times New Roman\',serif\"><span style=\"color:#000000\">&nbsp;Diploma engineers will demonstrate confidence to learn by self and exhibit ability for life-long learning.&nbsp;</span></span></span></li>\r\n	<li style=\"list-style-type:disc\"><span style=\"font-size:13.999999999999998pt\"><span style=\"font-family:\'Times New Roman\',serif\"><span style=\"color:#000000\">&nbsp;Diploma engineers will be able to take interest in research &amp; development in all disciplines of electrical engineering.&nbsp;</span></span></span></li>\r\n	<li style=\"list-style-type:disc\"><span style=\"font-size:13.999999999999998pt\"><span style=\"font-family:\'Times New Roman\',serif\"><span style=\"color:#000000\">&nbsp;Diploma engineers will be able to participate and succeed in competitive examinations.</span></span></span></li>\r\n</ul>\r\n', 1, 1, '2023-10-08 15:25:15', '2023-10-08 15:25:15', NULL, NULL),
(37, 1, 2, 28, 'Program Outcome', '<ul>\r\n	<li style=\"list-style-type:disc\"><span style=\"font-size:13.999999999999998pt\"><span style=\"font-family:\'Times New Roman\',serif\"><span style=\"color:#3a4d54\">Applicants should be good at organizing and solving problems; the ability to keep calm during a crisis.</span></span></span></li>\r\n	<li style=\"list-style-type:disc\"><span style=\"font-size:13.999999999999998pt\"><span style=\"font-family:\'Times New Roman\',serif\"><span style=\"color:#3a4d54\">The course is suitable for a professional career as an entrepreneur, a practicing engineer in industry, business, or government at an advanced level, or to pursue a Ph.D. degree in electrical engineering.</span></span></span></li>\r\n	<li style=\"list-style-type:disc\"><span style=\"font-size:13.999999999999998pt\"><span style=\"font-family:\'Times New Roman\',serif\"><span style=\"color:#3a4d54\">Candidates also possess detailed knowledge of electrical networks, electrical energy converters, equipment that uses electromagnetic field theory, electrical energy distribution systems, etc.</span></span></span></li>\r\n	<li style=\"list-style-type:disc\"><span style=\"font-size:13.999999999999998pt\"><span style=\"font-family:\'Times New Roman\',serif\"><span style=\"color:#3a4d54\">Along with various other personal attributes, one must also have dedication and commitment toward the profession.</span></span></span></li>\r\n</ul>\r\n', 1, 1, '2023-10-08 15:39:05', '2023-10-08 15:39:05', NULL, NULL),
(38, 1, 1, 3, 'program outcome', '<p><span style=\"font-size:13.999999999999998pt\"><span style=\"font-family:\'Times New Roman\',serif\"><span style=\"color:#000000\">1. Engineering knowledge: Apply the knowledge of mathematics, science, engineering fundamentals, and an engineering specialization to the solution of complex engineering problems.&nbsp;</span></span></span></p>\r\n\r\n<p><span style=\"font-size:13.999999999999998pt\"><span style=\"font-family:\'Times New Roman\',serif\"><span style=\"color:#000000\">2. Problem analysis: Identify, formulate, review research literature, and analyze complex engineering problems reaching substantiated conclusions using first principles of mathematics, natural sciences, and engineering sciences.&nbsp;</span></span></span></p>\r\n\r\n<p><span style=\"font-size:13.999999999999998pt\"><span style=\"font-family:\'Times New Roman\',serif\"><span style=\"color:#000000\">3. Design/development of solutions: Design solutions for complex engineering problems and design system components or processes that meet the specified needs with appropriate consideration for the public health and safety, and the cultural, societal, and environmental considerations.</span></span></span></p>\r\n\r\n<p><span style=\"font-size:13.999999999999998pt\"><span style=\"font-family:\'Times New Roman\',serif\"><span style=\"color:#000000\">&nbsp;4. Conduct investigations of complex problems: Use research-based knowledge and research methods including design of experiments, analysis and interpretation of data, and synthesis of the information to provide valid conclusions.&nbsp;</span></span></span></p>\r\n\r\n<p><span style=\"font-size:13.999999999999998pt\"><span style=\"font-family:\'Times New Roman\',serif\"><span style=\"color:#000000\">5. Modern tool usage: Create, select, and apply appropriate techniques, resources, and modern engineering and IT tools including prediction and modeling to complex engineering activities with an understanding of the limitations.</span></span></span></p>\r\n\r\n<p><span style=\"font-size:13.999999999999998pt\"><span style=\"font-family:\'Times New Roman\',serif\"><span style=\"color:#000000\">&nbsp;6. The engineer and society: Apply reasoning informed by the contextual knowledge to assess societal, health, safety, legal and cultural issues and the consequent responsibilities relevant to the professional engineering practice.&nbsp;</span></span></span></p>\r\n\r\n<p><span style=\"font-size:13.999999999999998pt\"><span style=\"font-family:\'Times New Roman\',serif\"><span style=\"color:#000000\">7. Environment and sustainability: Understand the impact of the professional engineering solutions in societal and environmental contexts, and demonstrate the knowledge of, and need for sustainable development.</span></span></span></p>\r\n\r\n<p><span style=\"font-size:13.999999999999998pt\"><span style=\"font-family:\'Times New Roman\',serif\"><span style=\"color:#000000\">&nbsp;8. Ethics: Apply ethical principles and commit to professional ethics and responsibilities and norms of the engineering practice.</span></span></span></p>\r\n\r\n<p><span style=\"font-size:13.999999999999998pt\"><span style=\"font-family:\'Times New Roman\',serif\"><span style=\"color:#000000\">&nbsp;9. Individual and team work: Function effectively as an individual, and as a member or leader in diverse teams, and in multidisciplinary settings.</span></span></span></p>\r\n\r\n<p><span style=\"font-size:13.999999999999998pt\"><span style=\"font-family:\'Times New Roman\',serif\"><span style=\"color:#000000\">&nbsp;10. Communication: Communicate effectively on complex engineering activities with the engineering community and with society at large, such as, being able to comprehend and write effective reports and design documentation, make effective presentations, and give and receive clear instructions.&nbsp;</span></span></span></p>\r\n\r\n<p><span style=\"font-size:13.999999999999998pt\"><span style=\"font-family:\'Times New Roman\',serif\"><span style=\"color:#000000\">11. Project management and finance: Demonstrate knowledge and understanding of the engineering and management principles and apply these to one&rsquo;s own work, as a member and leader in a team, to manage projects and in multidisciplinary environments.</span></span></span></p>\r\n\r\n<p><span style=\"font-size:13.999999999999998pt\"><span style=\"font-family:\'Times New Roman\',serif\"><span style=\"color:#000000\">&nbsp;12. Life-long learning: Recognize the need for, and have the preparation and ability to engage in independent and life-long learning in the broadest context of technological change</span></span></span></p>\r\n\r\n<p>&nbsp;</p>\r\n', 1, 1, '2023-10-09 07:26:07', '2023-10-09 07:26:07', NULL, NULL),
(39, 1, 1, 3, 'PO1: Engineering Knowledge', '<p style=\"text-align:justify\"><span style=\"text-align:justify\">Apply the knowledge of mathematics, science, engineering fundamentals, and an engineering specialization to the solution of complex engineering problems.</span></p>\r\n', 1, 0, '2023-10-09 07:35:46', '2023-10-09 07:35:46', NULL, NULL),
