(156, 8, 2, 196, 'Ethics', '<p>Apply ethical principles and commit to professional ethics and responsibilities and norms of the engineering practice.</p>\r\n', 1, 0, '2023-12-12 10:23:12', '2023-12-12 10:23:12', NULL, NULL),
(157, 8, 2, 196, 'Individual and team work', '<p>Function effectively as an individual, and as a member or leader in diverse teams, and in multidisciplinary settings.</p>\r\n', 1, 0, '2023-12-12 10:23:44', '2023-12-12 10:23:44', NULL, NULL),
(158, 8, 2, 196, 'Communication', '<p>Communicate effectively on complex engineering activities with the engineering community and with society at large, such as, being able to comprehend and write effective reports and design documentation, make effective presentations, and give and receive clear instructions.</p>\r\n', 1, 0, '2023-12-12 10:24:41', '2023-12-12 10:24:41', NULL, NULL),
(159, 8, 2, 196, 'Project management and finance', '<p>Demonstrate knowledge and understanding of the engineering andmanagement principles and apply these to own work, as a member and leader in a team, to manage projects and in multidisciplinary environments.</p>\r\n', 1, 0, '2023-12-12 10:25:14', '2023-12-12 10:25:14', NULL, NULL),
(160, 8, 2, 196, 'Life-long learning', '<p>Recognize the need for, and have the preparation and ability to engage in independent and life-long learning in the broadest context of technological change.</p>\r\n', 1, 0, '2023-12-12 10:25:39', '2023-12-12 10:25:39', NULL, NULL),
(161, 1, 5, 4, 'Engineering Knowledge', '<p>Apply knowledge of mathematics, science, engineering fundamentals, and an engineering specialization to the solution of complex engineering problems</p>\r\n', 1, 0, '2024-01-02 08:43:06', '2024-01-02 08:43:06', NULL, NULL),
(162, 1, 5, 4, 'Engineering knowledge', '<p>Apply knowledge of mathematics, science, engineering fundamentals, and an engineering specialization to the solution of complex engineering problems</p>\r\n', 1, 1, '2024-01-02 08:44:57', '2024-01-02 08:44:57', NULL, NULL),
(163, 1, 1, 2, 'Skills to Achieve', '<p>&bull; An ability to apply knowledge of mathematics, science and engineering fundamentals.<br />\r\n&bull; An ability to design and conduct experiments, as well as to analyze and interpret data<br />\r\n&bull; An ability to design mechanical engineering components and processes within economic, environmental, ethical and manufacturability constraints<br />\r\n&bull; An ability to function effectively in multidisciplinary teams.<br />\r\n&bull; An ability to identify, formulates, analyze and solve Mechanical Engineering problems.<br />\r\n&bull; An ability to understand professional, ethical and social responsibility.<br />\r\n&bull; An ability to communicate effectively through written reports or oral presentations.<br />\r\n&bull; The broad education necessary to understand the impact of engineering solutions in a global, economic, environmental, and societal context.<br />\r\n&bull; An ability to recognize the need and to engage in independent and life-long learning.<br />\r\n&bull; A knowledge of contemporary issues<br />\r\n&bull; An ability to use the appropriate techniques and modern engineering tools necessary for engineering practice.<br />\r\n&bull; An ability to apply the principles of management to one&rsquo;s own work, as a member and leader in a team, to manage projects.</p>\r\n', 1, 1, '2024-01-04 09:05:16', '2024-01-04 09:05:16', NULL, NULL),
(179, 1, 1, 23, 'Engineering knowledge', '<p style=\"text-align:justify\">Apply knowledge of mathematics, science, engineering fundamentals, and an engineering specialization to the solution of complex engineering problems.</p>\r\n', 1, 0, '2024-01-10 11:13:28', '2024-01-10 11:13:28', NULL, NULL),
(180, 1, 1, 23, 'Problem Analysis', '<p style=\"text-align:justify\">Identify, formulate, review research literature, and analyze complex engineering problems reaching substantiated conclusions using first principles of mathematics, natural sciences, and engineering sciences.</p>\r\n', 1, 0, '2024-01-10 11:13:28', '2024-01-10 11:13:28', NULL, NULL),
(181, 1, 1, 23, 'Design/development of solutions', '<p style=\"text-align:justify\">Design solutions for complex engineering problems and design system components or processes that meet the specified needs with appropriate consideration for the public health and safety, and the cultural, societal, and environmental considerations.</p>\r\n', 1, 0, '2024-01-10 11:13:28', '2024-01-10 11:13:28', NULL, NULL),
(182, 1, 1, 23, 'Conduct investigations of complex problems', '<p style=\"text-align:justify\">Use research-based knowledge and research methods including design of experiments, analysis and interpretation of data, and synthesis of the information to provide valid conclusions.</p>\r\n', 1, 0, '2024-01-10 11:13:28', '2024-01-10 11:13:28', NULL, NULL),
(183, 1, 1, 23, 'Modern Tool Usage', '<p style=\"text-align:justify\">Create, select, and apply appropriate techniques, resources, and modern engineering and IT tools including prediction and modeling to complex engineering activities with an understanding of the limitations.</p>\r\n', 1, 0, '2024-01-10 11:13:28', '2024-01-10 11:13:28', NULL, NULL),
(184, 1, 1, 23, 'The engineer and Society', '<p style=\"text-align:justify\">Apply reasoning informed by the contextual knowledge to assess societal, health, safety, legal and cultural issues and the consequent responsibilities relevant to the professional engineering practice.</p>\r\n', 1, 0, '2024-01-10 11:13:28', '2024-01-10 11:13:28', NULL, NULL),
(185, 1, 1, 23, 'Environment And Sustainability', '<p style=\"text-align:justify\">Understand the impact of the professional engineering solutions in societal and environmental contexts, and demonstrate the knowledge of, and need for sustainable development.</p>\r\n', 1, 0, '2024-01-10 11:13:28', '2024-01-10 11:13:28', NULL, NULL),
