(187, 1, 1, 23, 'Individual and Team Work', '<p style=\"text-align:justify\">Anction effectively as an individual, and as a member or leader in diverse teams, and in multidisciplinary settings.</p>\r\n', 1, 0, '2024-01-10 11:13:28', '2024-01-10 11:13:28', NULL, NULL),
(188, 1, 1, 23, 'Communication', '<p style=\"text-align:justify\">Communicate effectively on complex engineering activities with the engineering community and with society at large, such as, being able to comprehend and write effective reports and design documentation, make effective presentations, and give and receive clear instructions.</p>\r\n', 1, 0, '2024-01-10 11:13:28', '2024-01-10 11:13:28', NULL, NULL),
