INSERT INTO `tbl_program_outcome` (`id`, `faculty_id`, `level_id`, `program_id`, `title`, `content`, `is_active`, `is_delete`, `created_at`, `updated_at`, `created_by`, `updated_by`) VALUES
(378, 1, 1, 9, 'PO1', '<p><span style=\"font-family:Lucida Sans Unicode,Lucida Grande,sans-serif\"><span style=\"font-size:16px\"><strong>Engineering Knowledge:</strong></span></span><span style=\"font-family:Comic Sans MS,cursive\"> </span></p>\r\n\r\n<p><span style=\"font-family:Tahoma,Geneva,sans-serif\">Apply the principles of biotechnology and related engineering disciplines to solve complex problems.</span></p>\r\n', 1, 0, '2024-01-24 09:35:38', '2024-01-24 09:35:38', NULL, NULL),
(379, 1, 1, 9, 'PO2', '<p><span style=\"font-size:16px\"><span style=\"font-family:Lucida Sans Unicode,Lucida Grande,sans-serif\"><strong>Problem Analysis:</strong></span></span></p>\r\n\r\n<p><span style=\"font-family:Tahoma,Geneva,sans-serif\">Identify, formulate, review research literature, and analyze complex engineering problems related to biotechnology.</span></p>\r\n', 1, 0, '2024-01-24 09:37:02', '2024-01-24 09:37:02', NULL, NULL),
(380, 1, 1, 9, 'PO3', '<p><span style=\"font-family:Lucida Sans Unicode,Lucida Grande,sans-serif\"><span style=\"font-size:16px\"><strong>Design/Development of Solutions:</strong></span></span></p>\r\n\r\n<p><span style=\"font-family:Tahoma,Geneva,sans-serif\">Design solutions for complex biotechnological problems and design systems, components, or processes that meet specified needs with appropriate consideration for public health and safety, cultural, societal, and environmental considerations.</span></p>\r\n', 1, 0, '2024-01-24 09:39:42', '2024-01-24 09:39:42', NULL, NULL),
(381, 1, 1, 9, 'PO4', '<p><span style=\"font-family:Lucida Sans Unicode,Lucida Grande,sans-serif\"><span style=\"font-size:16px\"><strong>Conduct Investigations of Complex Problems:</strong></span></span></p>\r\n\r\n<p><span style=\"font-family:Tahoma,Geneva,sans-serif\">Use research-based knowledge and methods, including design of experiments, analysis and interpretation of data, and synthesis of information to provide valid conclusions in biotechnological settings.</span></p>\r\n', 1, 0, '2024-01-24 09:40:56', '2024-01-24 09:40:56', NULL, NULL),
(382, 1, 1, 9, 'PO5', '<p><span style=\"font-family:Lucida Sans Unicode,Lucida Grande,sans-serif\"><span style=\"font-size:16px\"><strong>Environment and Sustainability:</strong></span></span></p>\r\n\r\n<p><span style=\"font-family:Tahoma,Geneva,sans-serif\">Understand the impact of professional engineering solutions in societal and environmental contexts and demonstrate the knowledge of and need for sustainable development.</span></p>\r\n', 1, 0, '2024-01-24 09:42:04', '2024-01-24 09:42:04', NULL, NULL),
(383, 1, 1, 9, 'PO6', '<p><span style=\"font-family:Lucida Sans Unicode,Lucida Grande,sans-serif\"><span style=\"font-size:16px\"><strong>Communication:</strong></span></span></p>\r\n\r\n<p><span style=\"font-family:Tahoma,Geneva,sans-serif\">Communicate effectively on complex engineering activities with the engineering community and with society at large, such as being able to comprehend and write effective reports and design documentation, make effective presentations, and give and receive clear instructions.</span></p>\r\n', 1, 0, '2024-01-24 09:44:30', '2024-01-24 09:44:30', NULL, NULL),
(384, 1, 1, 9, 'PO7', '<p><span style=\"font-family:Lucida Sans Unicode,Lucida Grande,sans-serif\"><span style=\"font-size:16px\"><strong>Lifelong Learning:</strong></span></span></p>\r\n\r\n<p><span style=\"font-family:Tahoma,Geneva,sans-serif\">Recognize the need for and have the preparation and ability to engage in independent and lifelong learning in the broadest context of technological change.</span></p>\r\n', 1, 0, '2024-01-24 09:45:22', '2024-01-24 09:45:22', NULL, NULL),
(385, 1, 1, 10, 'P01', '<p><span style=\"font-family:Lucida Sans Unicode,Lucida Grande,sans-serif\"><span style=\"font-size:16px\"><strong>Engineering Knowledge:</strong></span></span></p>\r\n\r\n<p><span style=\"font-family:Tahoma,Geneva,sans-serif\">Apply principles of food science and technology to solve complex problems associated with food production, preservation, and safety.</span></p>\r\n', 1, 0, '2024-01-24 10:54:37', '2024-01-24 10:54:37', NULL, NULL),
(386, 1, 1, 10, 'PO2', '<p><span style=\"font-size:16px\"><span style=\"font-family:Lucida Sans Unicode,Lucida Grande,sans-serif\"><strong>Problem Analysis:</strong></span></span></p>\r\n\r\n<p><span style=\"font-family:Tahoma,Geneva,sans-serif\">Identify, analyze, and formulate solutions for challenges related to food processing and technology, drawing insights from relevant research literature.</span></p>\r\n', 1, 0, '2024-01-24 10:56:20', '2024-01-24 10:56:20', NULL, NULL),
(387, 1, 1, 10, 'PO3', '<p><span style=\"font-family:Lucida Sans Unicode,Lucida Grande,sans-serif\"><span style=\"font-size:16px\"><strong>Design/Development of Solutions:</strong></span></span></p>\r\n\r\n<p><span style=\"font-family:Tahoma,Geneva,sans-serif\">Design innovative solutions for food processing and technology, considering industry requirements and adhering to quality and safety standards.</span></p>\r\n', 1, 0, '2024-01-24 11:00:46', '2024-01-24 11:00:46', NULL, NULL),
(388, 1, 1, 10, 'PO4', '<p><span style=\"font-family:Lucida Sans Unicode,Lucida Grande,sans-serif\"><span style=\"font-size:16px\"><strong>Conduct Investigations of Complex Problems:</strong></span></span></p>\r\n\r\n<p><span style=\"font-family:Tahoma,Geneva,sans-serif\">Utilize research-based knowledge and methodologies, including experimental design and data analysis, to address complex issues in the realm of food technology.</span></p>\r\n', 1, 0, '2024-01-24 11:01:29', '2024-01-24 11:01:29', NULL, NULL),
(389, 1, 1, 10, 'PO5', '<p><span style=\"font-family:Lucida Sans Unicode,Lucida Grande,sans-serif\"><span style=\"font-size:16px\"><strong>The Engineer and Society:</strong></span></span></p>\r\n\r\n<p><span style=\"font-family:Tahoma,Geneva,sans-serif\">Evaluate the societal, health, safety, and environmental impact of food technology solutions, incorporating ethical considerations into professional practice.</span></p>\r\n', 1, 0, '2024-01-24 11:02:25', '2024-01-24 11:02:25', NULL, NULL),
(390, 1, 1, 10, 'PO6', '<p><span style=\"font-family:Lucida Sans Unicode,Lucida Grande,sans-serif\"><span style=\"font-size:16px\"><strong>Environment and Sustainability:</strong></span></span></p>\r\n\r\n<p><span style=\"font-family:Tahoma,Geneva,sans-serif\">Demonstrate an understanding of the environmental impact of food technology processes and practices, and advocate for sustainable development in the food industry.</span></p>\r\n', 1, 0, '2024-01-24 11:03:19', '2024-01-24 11:03:19', NULL, NULL),
(391, 1, 1, 10, 'PO7', '<p><span style=\"font-family:Lucida Sans Unicode,Lucida Grande,sans-serif\"><span style=\"font-size:16px\"><strong>Lifelong Learning:</strong></span></span></p>\r\n\r\n<p><span style=\"font-family:Tahoma,Geneva,sans-serif\">Recognize the need for continuous learning, keeping abreast of technological advancements, and engaging in lifelong learning to adapt to evolving challenges in the field of food technology.</span></p>\r\n', 1, 0, '2024-01-24 11:04:24', '2024-01-24 11:04:24', NULL, NULL),
(392, 6, 1, 77, 'Foundational Knowledge', '<p>Demonstrate a solid understanding of fundamental economic principles, theories, and concepts</p>\r\n', 1, 0, '2024-01-29 06:01:57', '2024-01-29 06:01:57', NULL, NULL),
(393, 6, 1, 77, 'Analytical Skills', '<p>Develop and apply quantitative and qualitative analytical skills to evaluate economic phenomena and trends.</p>\r\n', 1, 0, '2024-01-29 06:03:06', '2024-01-29 06:03:06', NULL, NULL),
(394, 6, 1, 77, 'Research Abilities', '<p>Acquire basic research skills to critically assess economic literature and conduct independent research.</p>\r\n', 1, 0, '2024-01-29 06:06:15', '2024-01-29 06:06:15', NULL, NULL),
(395, 6, 1, 77, 'Communication Skills', '<p>Effectively communicate economic ideas and analyses in both written and verbal forms to diverse audiences.</p>\r\n', 1, 0, '2024-01-29 06:07:21', '2024-01-29 06:07:21', NULL, NULL),
(396, 6, 1, 77, 'Interdisciplinary Understanding', '<p>Appreciate the interdisciplinary nature of economics by recognizing its connections with other social sciences.</p>\r\n', 1, 0, '2024-01-29 06:10:16', '2024-01-29 06:10:16', NULL, NULL),
(397, 6, 1, 77, 'Global Perspective', '<p>Understand the global dimensions of economic issues, considering international trade, development, and cooperation.</p>\r\n', 1, 0, '2024-01-29 06:11:39', '2024-01-29 06:11:39', NULL, NULL),
(398, 6, 1, 77, 'Ethical Awareness', '<p>Recognize and address ethical considerations in economic decision-making and analysis.</p>\r\n', 1, 0, '2024-01-29 06:12:14', '2024-01-29 06:12:14', NULL, NULL),
(399, 6, 1, 77, 'Problem Solving', '<p>&nbsp;Apply economic principles to real-world problems, developing solutions with a focus on practicality and feasibility.</p>\r\n', 1, 0, '2024-01-29 06:12:45', '2024-01-29 06:12:45', NULL, NULL),
(400, 6, 2, 82, 'Research Proficiency', '<p>Demonstrate advanced research skills through the completion of a thesis or capstone project, contributing to the academic discourse.</p>\r\n', 1, 0, '2024-01-29 06:15:40', '2024-01-29 06:15:40', NULL, NULL),
(401, 6, 2, 82, 'Specialization Expertise', '<p>Develop expertise in a specific area of economics, such as financial economics, international economics, or public policy.</p>\r\n', 1, 0, '2024-01-29 06:16:19', '2024-01-29 06:16:19', NULL, NULL),
(402, 6, 2, 82, 'Policy Analysis', '<p>&nbsp;Analyze and evaluate economic policies, providing informed recommendations for decision-makers.</p>\r\n', 1, 0, '2024-01-29 06:16:45', '2024-01-29 06:16:45', NULL, NULL),
(403, 6, 2, 82, 'Critical Thinking', '<p>Cultivate critical thinking skills to assess economic issues and challenges from multiple perspectives.</p>\r\n', 1, 0, '2024-01-29 06:17:44', '2024-01-29 06:17:44', NULL, NULL),
(404, 6, 2, 82, 'Professional Communication', '<p>Communicate complex economic analyses effectively, tailoring messages to various stakeholders.</p>\r\n', 1, 0, '2024-01-29 06:19:00', '2024-01-29 06:19:00', NULL, NULL),
(405, 6, 2, 82, 'Global Awareness', '<p>Navigate the complexities of the global economic landscape, understanding interconnectedness and implications for decision-making.</p>\r\n', 1, 0, '2024-01-29 06:19:43', '2024-01-29 06:19:43', NULL, NULL),
(406, 6, 2, 82, 'Leadership and Adaptability', '<p>Demonstrate leadership qualities and adaptability, preparing graduates for leadership roles in academia, research, government, or the private sector.</p>\r\n', 1, 0, '2024-01-29 06:28:57', '2024-01-29 06:28:57', NULL, NULL),
(407, 6, 1, 74, 'PO1: Literary Proficiency and Analysis', '<p>Attain a comprehensive understanding of diverse literary genres, historical periods, and cultural contexts, demonstrating the ability to critically analyze and interpret literary texts.</p>\r\n', 1, 0, '2024-01-29 06:35:50', '2024-01-29 06:35:50', NULL, NULL),
(408, 6, 1, 74, 'PO2: Effective Communication Skills', '<p>Demonstrate strong written and oral communication skills, enabling clear, persuasive, and creative expression of ideas in academic and professional settings.</p>\r\n', 1, 0, '2024-01-29 06:36:24', '2024-01-29 06:36:24', NULL, NULL),
(409, 6, 1, 74, 'PO3: Critical Thinking and Analytical Abilities', '<p>Develop robust critical thinking skills for the analysis, evaluation, and synthesis of complex information, arguments, and perspectives within the realm of English literature.</p>\r\n', 1, 0, '2024-01-29 06:38:27', '2024-01-29 06:38:27', NULL, NULL),
(410, 6, 1, 74, 'PO4: Research Competence', '<p>Display proficiency in independent research, utilizing appropriate methodologies and contributing original insights to the scholarly discourse within English literature.</p>\r\n', 1, 0, '2024-01-29 06:39:21', '2024-01-29 06:39:21', NULL, NULL),
(411, 6, 1, 74, 'PO5: Cultural and Global Awareness', '<p>Cultivate an appreciation for diverse cultural expressions and global perspectives within literature, fostering intercultural competence and understanding the interconnectedness of world literature</p>\r\n', 1, 0, '2024-01-29 06:39:50', '2024-01-29 06:39:50', NULL, NULL),
(412, 6, 1, 74, 'PO6: Creative Expression', '<p>Demonstrate the ability to engage in creative expression through various literary forms, such as crafting poetry, fiction, or drama, showcasing imaginative and expressive capacities.</p>\r\n', 1, 0, '2024-01-29 06:40:39', '2024-01-29 06:40:39', NULL, NULL),
(413, 6, 1, 74, 'PO7: Ethical and Social Responsibility', '<p>Recognize the ethical dimensions of literature and exhibit a sense of social responsibility, understanding the impact of literature on society, and engaging with texts that address social justice and ethical issues.</p>\r\n', 1, 0, '2024-01-29 09:21:46', '2024-01-29 09:21:46', NULL, NULL),
(414, 6, 1, 74, 'PO8: Collaboration and Interdisciplinary Skills', '<p>Develop effective collaboration and interdisciplinary skills, working seamlessly with diverse teams and integrating insights from related disciplines to enrich the understanding of literature.</p>\r\n', 1, 0, '2024-01-29 09:22:35', '2024-01-29 09:22:35', NULL, NULL),
(415, 6, 2, 78, 'PO1: Advanced Literary Analysis', '<p>Demonstrate advanced proficiency in analyzing and interpreting a wide range of literary genres, periods, and cultural contexts, incorporating sophisticated critical perspectives.</p>\r\n', 1, 0, '2024-01-29 09:23:46', '2024-01-29 09:23:46', NULL, NULL),
(416, 6, 2, 78, 'PO2: Research Mastery', '<p>Exhibit advanced research skills, including the ability to formulate research questions, design and execute independent research projects, and contribute original insights to the scholarly discourse within English literature.</p>\r\n', 1, 0, '2024-01-29 09:24:14', '2024-01-29 09:24:14', NULL, NULL),
(417, 6, 2, 78, 'PO3: Theoretical Understanding', '<p>Develop a deep understanding of literary theories and critical approaches, applying them effectively to analyze and interpret complex literary texts.</p>\r\n', 1, 0, '2024-01-29 09:24:41', '2024-01-29 09:24:41', NULL, NULL),
(418, 6, 2, 78, 'PO4: Literary Criticism and Evaluation', '<p>Engage in advanced literary criticism, demonstrating the ability to evaluate and critique scholarly interpretations and contribute substantively to ongoing critical conversations.</p>\r\n', 1, 0, '2024-01-29 09:25:11', '2024-01-29 09:25:11', NULL, NULL),
(419, 6, 2, 78, 'PO5: Professional Writing and Presentation', '<p><span style=\"display:none\">&nbsp;</span><span style=\"display:none\">&nbsp;</span><span style=\"display:none\">&nbsp;</span><span style=\"display:none\">&nbsp;</span><span style=\"display:none\">&nbsp;</span><span style=\"display:none\">&nbsp;</span><span style=\"display:none\">&nbsp;</span><span style=\"display:none\">&nbsp;</span><span style=\"display:none\">&nbsp;</span><span style=\"display:none\">&nbsp;</span><span style=\"display:none\">&nbsp;</span><span style=\"display:none\">&nbsp;</span><span style=\"display:none\">&nbsp;</span>Demonstrate advanced proficiency in professional writing and presentation skills, including the ability to produce scholarly articles, conference papers, and other academic publications.<span style=\"display:none\">&nbsp;</span><span style=\"display:none\">&nbsp;</span><span style=\"display:none\">&nbsp;</span><span style=\"display:none\">&nbsp;</span><span style=\"display:none\">&nbsp;</span><span style=\"display:none\">&nbsp;</span><span style=\"display:none\">&nbsp;</span><span style=\"display:none\">&nbsp;</span><span style=\"display:none\">&nbsp;</span><span style=\"display:none\">&nbsp;</span></p>\r\n', 1, 0, '2024-01-29 09:26:28', '2024-01-29 09:26:28', NULL, NULL),
(420, 6, 2, 78, 'PO6: Interdisciplinary Connections', '<p>Establish connections between English literature and related disciplines, demonstrating the ability to integrate insights from interdisciplinary perspectives into literary analysis.</p>\r\n', 1, 0, '2024-01-29 09:26:58', '2024-01-29 09:26:58', NULL, NULL),
(421, 6, 2, 78, 'PO7: Global and Comparative Perspectives', '<p>Cultivate a global and comparative understanding of literature, recognizing the interconnectedness of literary traditions across cultures and appreciating diverse global perspectives.</p>\r\n', 1, 0, '2024-01-29 09:27:22', '2024-01-29 09:27:22', NULL, NULL),
(422, 6, 2, 78, 'PO8: Ethical and Social Implications', '<p>Recognize and analyze the ethical and social implications within literary texts, considering the broader impact of literature on societal values, norms, and perceptions.</p>\r\n', 1, 0, '2024-01-29 09:28:02', '2024-01-29 09:28:02', NULL, NULL),
(423, 6, 2, 78, 'PO9: Teaching and Pedagogical Skills', '<p>Develop advanced teaching and pedagogical skills for effectively conveying complex literary concepts, fostering critical thinking, and engaging students in meaningful discussions.</p>\r\n', 1, 0, '2024-01-29 09:28:31', '2024-01-29 09:28:31', NULL, NULL),
(424, 6, 2, 78, 'PO10: Professional Development', '<p>Prepare for professional roles in academia, publishing, research institutions, or related fields by acquiring advanced skills, knowledge, and a deep understanding of current trends in English literature and related industries.</p>\r\n', 1, 0, '2024-01-29 09:28:59', '2024-01-29 09:28:59', NULL, NULL),
(425, 11, 7, 141, 'Employability', '<ul>\r\n	<li style=\"text-align:justify\">Employ highly developed conceptual, analytical, quantitative and technical skills and are adapt with a range of technologies.</li>\r\n	<li style=\"text-align:justify\">Apply advanced knowledge of clinical biochemistry,&nbsp;hematology,&nbsp;microbiology,&nbsp;immunology,&nbsp;and other relevant disciplines to laboratory testing and analysis.</li>\r\n	<li style=\"text-align:justify\">Perform a wide range of diagnostic tests and procedures accurately and efficiently using advanced laboratory equipment and technology.</li>\r\n</ul>\r\n', 1, 0, '2024-02-04 01:29:30', '2024-02-04 01:29:30', NULL, NULL),
(426, 11, 7, 141, 'Professionalism and communication:', '<ul>\r\n	<li style=\"text-align: justify;\">Communicate effectively with healthcare professionals,&nbsp;patients,&nbsp;and the public,&nbsp;both verbally and in writing.</li>\r\n	<li style=\"text-align: justify;\">Demonstrate professionalism and ethical conduct in all aspects of their work.</li>\r\n	<li style=\"text-align: justify;\">Function effectively as part of a multidisciplinary healthcare team.</li>\r\n</ul>\r\n', 1, 0, '2024-02-04 01:33:41', '2024-02-04 01:33:41', NULL, NULL),
(427, 11, 7, 141, 'Problem-solving and critical thinking:', '<ul>\r\n	<li>Solve technical problems related to laboratory procedures and equipment troubleshooting.</li>\r\n	<li>Think critically and independently to evaluate laboratory results and suggest appropriate courses of action.</li>\r\n	<li>Adapt to run time new situations and technologies with a flexible and innovative approach.</li>\r\n</ul>\r\n', 1, 0, '2024-02-04 01:35:00', '2024-02-04 01:35:00', NULL, NULL),
(428, 1, 5, 4, 'Engineering Knowledge', '<p>Apply knowledge of mathematics, science, engineering fundamentals, and an engineering specialization to the solution of complex engineering problems.</p>\r\n', 1, 1, '2024-02-07 03:40:41', '2024-02-07 03:40:41', NULL, NULL),
(429, 1, 5, 25, 'Title', '<p>DEMO&nbsp;</p>\r\n', 1, 1, '2024-02-13 08:15:48', '2024-02-13 08:15:48', NULL, NULL),
(430, 1, 5, 25, 'Engineering Knowledge', '<p>Apply knowledge of mathematics, science, engineering fundamentals, and an engineering specialization to the solution of complex engineering problems.</p>\r\n', 1, 1, '2024-02-17 06:56:06', '2024-02-17 06:56:06', NULL, NULL),
(431, 1, 5, 25, 'Problem analysis', '<p>Identify, formulate, review research literature, and analyze complex engineering problems reaching substantiated conclusions using first principles of mathematics, natural sciences, and engineering sciences.</p>\r\n', 1, 0, '2024-02-17 06:56:54', '2024-02-17 06:56:54', NULL, NULL),
(432, 1, 5, 25, 'Design/development of solutions', '<p>Design solutions for complex engineering problems and design system components or processes that meet the specified needs with appropriate consideration for the public health and safety, and the cultural, societal, and environmental considerations.</p>\r\n', 1, 0, '2024-02-17 06:57:26', '2024-02-17 06:57:26', NULL, NULL),
(433, 1, 5, 25, 'Conduct investigations of complex problems', '<p>Use research-based knowledge and research methods including design of experiments, analysis and interpretation of data, and synthesis of the information to provide valid conclusions.</p>\r\n', 1, 0, '2024-02-17 06:57:59', '2024-02-17 06:57:59', NULL, NULL),
(434, 1, 5, 25, 'Modern tool usage', '<p>Create, select, and apply appropriate techniques, resources, and modern engineering and IT tools including prediction and modeling to complex engineering activities with an understanding of the limitations.</p>\r\n', 1, 0, '2024-02-17 06:58:28', '2024-02-17 06:58:28', NULL, NULL),
(435, 1, 5, 25, 'The engineer and society', '<p>Apply reasoning informed by the contextual knowledge to assess societal, health, safety, legal and cultural issues and the consequent responsibilities relevant to the professional engineering practice.</p>\r\n', 1, 0, '2024-02-17 06:58:57', '2024-02-17 06:58:57', NULL, NULL),
(436, 1, 5, 25, 'Environment And Sustainability', '<p>Understand the impact of the professional engineering solutions in societal and environmental contexts, and demonstrate the knowledge of, and need for sustainable development.</p>\r\n', 1, 0, '2024-02-17 06:59:39', '2024-02-17 06:59:39', NULL, NULL),
(437, 6, 1, 75, 'Foundational Knowledge', '<p>Acquire a solid understanding of core psychological theories, concepts, and historical perspectives.</p>\r\n', 1, 0, '2024-02-17 07:59:36', '2024-02-17 07:59:36', NULL, NULL),
(438, 6, 1, 75, 'Research Skills', '<p>Develop the ability to critically assess and conduct research, including designing studies, collecting data, and analyzing findings.</p>\r\n', 1, 0, '2024-02-17 08:00:18', '2024-02-17 08:00:18', NULL, NULL),
(439, 6, 1, 75, 'Applied Understanding', '<p>Apply psychological principles to real-world situations, analyzing and addressing various behavioral and mental health challenges.</p>\r\n', 1, 0, '2024-02-17 08:00:40', '2024-02-17 08:00:40', NULL, NULL),
(440, 1, 5, 25, 'Ethics', '<p>Apply ethical principles and commit to professional ethics and responsibilities and norms of the engineering practice.</p>\r\n', 1, 0, '2024-02-17 09:03:00', '2024-02-17 09:03:00', NULL, NULL),
(441, 1, 5, 25, 'Individual and team work', '<p>function effectively as an individual, and as a member or leader in diverse teams, and in multidisciplinary settings.</p>\r\n', 1, 0, '2024-02-17 09:03:26', '2024-02-17 09:03:26', NULL, NULL),
(442, 1, 5, 25, 'Communication', '<p>Communicate effectively on complex engineering activities with the engineering community and with society at large, such as, being able to comprehend and write effective reports and design documentation, make effective presentations, and give and receive clear instructions.</p>\r\n', 1, 0, '2024-02-17 09:03:46', '2024-02-17 09:03:46', NULL, NULL),
(443, 1, 5, 25, 'Project management and finance', '<p>Demonstrate knowledge and understanding of the engineering andmanagement principles andapply these toone&acirc;&euro;&tilde;s own work, as a member and leader in a team, to manage projects and in multidisciplinary environments</p>\r\n', 1, 0, '2024-02-17 09:04:10', '2024-02-17 09:04:10', NULL, NULL),
(444, 1, 5, 25, 'Life-long learning', '<p>Recognize the need for, and have the preparation and ability to engage in independent and life-long learning in the broadest context of technological change.</p>\r\n', 1, 0, '2024-02-17 09:04:44', '2024-02-17 09:04:44', NULL, NULL),
(445, 1, 5, 25, 'Engineering Knowledge', '<p>Apply knowledge of mathematics, science, engineering fundamentals, and an engineering specialization to the solution of complex engineering problems</p>\r\n', 1, 1, '2024-02-17 09:05:05', '2024-02-17 09:05:05', NULL, NULL),
(446, 6, 1, 75, 'Communication Skills', '<p>Effectively convey psychological concepts and research findings through written and oral means to diverse audiences.</p>\r\n', 1, 0, '2024-02-17 09:27:06', '2024-02-17 09:27:06', NULL, NULL),
(447, 6, 1, 75, 'Cultural Competence', '<p>Recognize and appreciate the impact of cultural diversity on human behavior, adapting psychological principles to diverse populations.</p>\r\n', 1, 0, '2024-02-17 09:28:16', '2024-02-17 09:28:16', NULL, NULL),
(448, 6, 1, 75, ' Critical Thinking', '<p>Cultivate strong critical thinking skills to analyze, synthesize, and evaluate information related to psychological phenomena.</p>\r\n', 1, 0, '2024-02-17 09:28:38', '2024-02-17 09:28:38', NULL, NULL),
(449, 6, 2, 81, 'Advanced Theoretical Understanding', '<p>Demonstrate advanced and nuanced comprehension of psychological theories, models, and frameworks.</p>\r\n', 1, 0, '2024-02-17 09:30:11', '2024-02-17 09:30:11', NULL, NULL),
(450, 6, 2, 81, 'Research Proficiency', '<p>Conduct independent, sophisticated research contributing to the existing body of knowledge within the chosen specialization.</p>\r\n', 1, 0, '2024-02-17 09:31:19', '2024-02-17 09:31:19', NULL, NULL),
(451, 6, 2, 81, 'Clinical and Applied Skills', '<p>Develop advanced clinical and applied skills, applying psychological theories to assess, diagnose, and intervene in various psychological issues.</p>\r\n', 1, 0, '2024-02-17 09:32:31', '2024-02-17 09:32:31', NULL, NULL),
(452, 6, 2, 81, 'Leadership and Supervisory Skills', '<p>Exhibit leadership and supervisory capabilities, guiding and mentoring individuals or teams in professional settings.</p>\r\n', 1, 0, '2024-02-17 09:33:25', '2024-02-17 09:33:25', NULL, NULL),
(453, 6, 2, 81, 'Specialization Competence', '<p>Specialize in a particular area within psychology, demonstrating expertise and contributing to advancements in that specific field.</p>\r\n', 1, 0, '2024-02-17 09:34:33', '2024-02-17 09:34:33', NULL, NULL),
(454, 6, 2, 81, 'Ethical Decision-Making', '<p>Engage in ethical decision-making and demonstrate a deep understanding of ethical considerations in both research and professional practice.</p>\r\n', 1, 0, '2024-02-17 09:35:00', '2024-02-17 09:35:00', NULL, NULL),
(455, 6, 1, 73, 'Conceptual Mastery', '<p>Demonstrate a profound understanding of the basic concepts, theories, historical perspectives, and analytical perceptions within political science, encompassing political institutions and processes.</p>\r\n', 1, 0, '2024-02-17 09:45:57', '2024-02-17 09:45:57', NULL, NULL),
(456, 6, 1, 73, 'Constitutional Insight', '<p>Develop familiarity with the origin and evolution of constitutional provisions guiding state policy, political processes, and the protection of people&#39;s rights, analyzing their impact on political issues at both local and national levels.</p>\r\n', 1, 0, '2024-02-17 09:46:55', '2024-02-17 09:46:55', NULL, NULL),
(457, 6, 1, 73, 'Public Administration Competence', '<p>Acquire a comprehensive understanding of fundamental concepts and issues related to administration, management, recruitment, and training in public administration.</p>\r\n', 1, 0, '2024-02-17 09:48:10', '2024-02-17 09:48:10', NULL, NULL),
(458, 6, 1, 75, 'Analytical Skills in Governance', '<p>Exhibit analytical prowess in assessing basic concepts and issues associated with planning, development, public services, and public financial administration in India.</p>\r\n', 1, 0, '2024-02-17 09:48:52', '2024-02-17 09:48:52', NULL, NULL),
(459, 6, 1, 73, 'Global Political Acumen', '<p>Develop acquaintance with key concepts and issues in international relations, exploring important developments in terms of theory, actors, institutions, and processes.</p>\r\n', 1, 0, '2024-02-17 09:49:32', '2024-02-17 09:49:32', NULL, NULL),
(460, 6, 1, 73, 'Foreign Policy Understanding', '<p>Comprehend the principles of India&#39;s foreign policy, including its central realities, issues, and contemporary developments, with a focus on major bilateral and multilateral engagements and economic and political challenges.</p>\r\n', 1, 0, '2024-02-17 09:50:05', '2024-02-17 09:50:05', NULL, NULL),
(461, 6, 1, 73, 'Philosophical Inquiry in Politics', '<p>Engage in critical examination of philosophical themes in Western Political Thinking by studying select political thinkers from the early Greek period to modern times.</p>\r\n', 1, 0, '2024-02-17 09:50:58', '2024-02-17 09:50:58', NULL, NULL),
(462, 6, 2, 83, 'Conceptual Mastery', '<p>Demonstrate a profound understanding of the basic concepts, theories, historical perspectives, and analytical perceptions within political science, encompassing political institutions and processes.</p>\r\n', 1, 0, '2024-02-17 09:52:23', '2024-02-17 09:52:23', NULL, NULL),
