(468, 6, 1, 76, 'Understanding Social Institutions', '<p>: Acquire comprehensive knowledge of social institutions, demonstrating an understanding of their structures, functions, and impacts on society.</p>\r\n', 1, 0, '2024-02-17 10:04:13', '2024-02-17 10:04:13', NULL, NULL),
(469, 6, 1, 76, 'Exploration of Race, Class, and Gender', '<p>Investigate and comprehend the intersections of race, class, and gender, exploring their impact on individual experiences and societal structures.</p>\r\n', 1, 0, '2024-02-17 10:08:57', '2024-02-17 10:08:57', NULL, NULL),
(470, 6, 1, 76, 'Social Anthropology Understanding', '<p>Acquire knowledge in social anthropology, exploring cultural diversity and understanding the dynamics of social relationships in various cultural contexts.</p>\r\n', 1, 0, '2024-02-17 10:10:28', '2024-02-17 10:10:28', NULL, NULL),
(471, 6, 1, 76, 'Knowledge of Labour Legislation and Social Welfare', '<p>Understand labour legislation and social welfare policies, assessing their impact on individuals, communities, and society at large.</p>\r\n', 1, 0, '2024-02-17 10:11:47', '2024-02-17 10:11:47', NULL, NULL),
(472, 6, 1, 76, 'Social Psychology Insight', '<p>Gain insight into social psychology, understanding the psychological processes underlying individual and group behavior within societal contexts.</p>\r\n', 1, 0, '2024-02-17 10:12:21', '2024-02-17 10:12:21', NULL, NULL),
(473, 6, 1, 76, 'Understanding Social Movements', '<p>Explore the dynamics of social movements, analyzing their origins, development, and impact on societal change.</p>\r\n', 1, 0, '2024-02-17 10:12:58', '2024-02-17 10:12:58', NULL, NULL),
(474, 6, 1, 76, 'Globalization Awareness', '<p>Develop an awareness of globalization and its effects on societies, examining the interconnectedness of cultures, economies, and social structures on a global scale.</p>\r\n', 1, 0, '2024-02-17 10:13:40', '2024-02-17 10:13:40', NULL, NULL),
