(583, 1, 3, 14, 'Engineering Knowledge', '<p>Apply knowledge of mathematics, science, engineering fundamentals, and an engineering specialization to the solution of complex engineering problems.</p>\r\n', 1, 0, '2024-02-21 10:28:37', '2024-02-21 10:28:37', NULL, NULL),
(584, 16, 6, 153, 'Problem analysis', '<p>Identify, formulate, review research literature, and analyze complex engineering problems reaching substantiated conclusions using first principles of mathematics, natural sciences, and engineering sciences.</p>\r\n', 1, 0, '2024-02-21 10:29:05', '2024-02-21 10:29:05', NULL, NULL),
(585, 16, 6, 153, 'Design/development of solutions', '<p>Design solutions for complex engineering problems and design system components or processes that meet the specified needs with appropriate consideration for the public health and safety, and the cultural, societal, and environmental considerations.</p>\r\n', 1, 0, '2024-02-21 10:30:04', '2024-02-21 10:30:04', NULL, NULL),
(586, 16, 6, 153, 'Conduct investigations of complex problems', '<p>Use research-based knowledge and research methods including design of experiments, analysis and interpretation of data, and synthesis of the information to provide valid conclusions.</p>\r\n', 1, 0, '2024-02-21 10:30:39', '2024-02-21 10:30:39', NULL, NULL),
(587, 16, 6, 153, 'Modern tool usage', '<p>Create, select, and apply appropriate techniques, resources, and modern engineering and IT tools including prediction and modeling to complex engineering activities with an understanding of the limitations.</p>\r\n', 1, 0, '2024-02-21 10:31:07', '2024-02-21 10:31:07', NULL, NULL),
(588, 16, 6, 153, 'The engineer and society', '<p>Apply reasoning informed by the contextual knowledge to assess societal, health, safety, legal and cultural issues and the consequent responsibilities relevant to the professional engineering practice.</p>\r\n', 1, 0, '2024-02-21 10:31:45', '2024-02-21 10:31:45', NULL, NULL),
(589, 16, 6, 153, 'Environment And Sustainability', '<p>Understand the impact of the professional engineering solutions in societal and environmental contexts, and demonstrate the knowledge of, and need for sustainable development.</p>\r\n', 1, 0, '2024-02-21 10:32:36', '2024-02-21 10:32:36', NULL, NULL),
(590, 16, 6, 153, 'Ethics', '<p>Apply ethical principles and commit to professional ethics and responsibilities and norms of the engineering practice.</p>\r\n', 1, 0, '2024-02-21 10:33:08', '2024-02-21 10:33:08', NULL, NULL),
(591, 16, 6, 153, 'Individual and team work', '<p>Function effectively as an individual, and as a member or leader in diverse teams, and in multidisciplinary settings.</p>\r\n', 1, 0, '2024-02-21 10:33:44', '2024-02-21 10:33:44', NULL, NULL),
(592, 16, 6, 153, 'Communication', '<p>Communicate effectively on complex engineering activities with the engineering community and with society at large, such as, being able to comprehend and write effective reports and design documentation, make effective presentations, and give and receive clear instructions.</p>\r\n', 1, 0, '2024-02-21 10:34:14', '2024-02-21 10:34:14', NULL, NULL),
(593, 16, 6, 153, 'Project management and finance', '<p>Demonstrate knowledge and understanding of the engineering andmanagement principles andapply these toone&acirc;&euro;&tilde;s own work, as a member and leader in a team, to manage projects and in multidisciplinary environments.</p>\r\n', 1, 0, '2024-02-21 10:34:38', '2024-02-21 10:34:38', NULL, NULL),
(594, 16, 6, 153, 'Life-long learning', '<p>Recognize the need for, and have the preparation and ability to engage in independent and life-long learning in the broadest context of technological change.</p>\r\n', 1, 0, '2024-02-21 10:35:01', '2024-02-21 10:35:01', NULL, NULL),
(595, 16, 6, 153, 'Engineering Knowledge', '<p>Apply knowledge of mathematics, science, engineering fundamentals, and an engineering specialization to the solution of complex engineering problems.</p>\r\n', 1, 0, '2024-02-21 10:36:29', '2024-02-21 10:36:29', NULL, NULL),
(596, 5, 1, 60, 'Program Outcomes', '<ul>\r\n	<li>Graduates will develop strong leadership abilities, enabling them to guide and inspire teams towards achieving organizational goals.</li>\r\n	<li>Students will gain proficiency in making informed and strategic decisions, equipping them to address complex business challenges.</li>\r\n	<li>The program hones communication skills, ensuring graduates can convey ideas clearly, and fostering collaboration in diverse professional settings.</li>\r\n	<li>The curriculum instills an understanding of global business trends, preparing students to thrive in an interconnected and dynamic international landscape.</li>\r\n	<li>Emphasis is placed on ethical considerations, enabling graduates to make principled decisions that contribute to responsible and sustainable business practices.</li>\r\n	<li>Students will cultivate effective teamwork skills, learning to collaborate with diverse individuals to achieve collective objectives.</li>\r\n	<li>The program fosters adaptability and innovation, empowering graduates to navigate change and contribute to the development of innovative solutions within organizations.</li>\r\n	<li>Graduates will possess the skills to plan, execute, and oversee projects efficiently, meeting objectives within specified timelines and budgets.</li>\r\n	<li>The curriculum encourages an entrepreneurial mindset, equipping students with the skills and mindset to identify opportunities and drive business innovation.</li>\r\n</ul>\r\n', 1, 0, '2024-02-29 03:30:34', '2024-02-29 03:30:34', NULL, NULL),
