(624, 6, 1, 221, 'Historical Knowledge Mastery', '<p>Develop a comprehensive mastery of historical knowledge, including key events, civilizations, and significant historical developments from various periods.</p>\r\n', 1, 0, '2024-03-08 06:19:01', '2024-03-08 06:19:01', NULL, NULL),
(625, 6, 1, 221, 'Historiographical Awareness', '<p>Acquire awareness of historiographical debates and different approaches to interpreting history, understanding the evolving nature of historical scholarship.</p>\r\n', 1, 0, '2024-03-08 06:19:40', '2024-03-08 06:19:40', NULL, NULL),
(626, 6, 1, 221, 'Research Skills in History', '<p>Develop research skills in historical inquiry, including the ability to locate, analyze, and synthesize historical sources to construct well-supported arguments.</p>\r\n', 1, 0, '2024-03-08 06:20:13', '2024-03-08 06:20:13', NULL, NULL),
(627, 6, 1, 221, 'Understanding Historical Contexts', '<p>Gain an understanding of historical contexts, recognizing the interconnectedness of events and developments within specific time periods.</p>\r\n', 1, 0, '2024-03-08 06:21:46', '2024-03-08 06:21:46', NULL, NULL),
(628, 6, 1, 221, 'Cultural and Social History Appreciation', '<p>Appreciate the cultural and social dimensions of historical events, understanding the impact of historical processes on societies and individuals.</p>\r\n', 1, 0, '2024-03-08 06:23:08', '2024-03-08 06:23:08', NULL, NULL),
(629, 6, 1, 221, 'Global Historical Perspectives', '<p>Develop global historical perspectives, recognizing the interconnectedness of historical events and their implications on a global scale.</p>\r\n', 1, 0, '2024-03-08 06:26:18', '2024-03-08 06:26:18', NULL, NULL),
(630, 6, 1, 221, 'Understanding Historical Change and Continuity', '<p>Analyze patterns of historical change and continuity, identifying factors that contribute to the evolution of societies over time.</p>\r\n', 1, 0, '2024-03-08 06:26:55', '2024-03-08 06:26:55', NULL, NULL),
(631, 6, 1, 221, 'Applied History Skills', '<p>Apply historical knowledge and skills to contemporary issues, demonstrating the relevance of historical understanding in addressing present-day challenges.</p>\r\n', 1, 0, '2024-03-08 06:27:23', '2024-03-08 06:27:23', NULL, NULL),
(632, 6, 2, 224, 'Explanatory Proficiency', '<p>Demonstrate the capacity to articulate the causes and reasons behind significant historical events, offering clear explanations for their occurrence.</p>\r\n', 1, 0, '2024-03-08 06:29:47', '2024-03-08 06:29:47', NULL, NULL),
(633, 6, 2, 224, 'Historical Methodology Understanding', '<p>Possess a deep understanding of the historical method of study, applying systematic approaches to analyze and interpret historical phenomena.</p>\r\n', 1, 0, '2024-03-08 06:31:26', '2024-03-08 06:31:26', NULL, NULL),
(634, 6, 2, 224, 'Evidence Interpretation', '<p>Exhibit a clear understanding of the evidence collected from historical sources, demonstrating the ability to interpret and evaluate primary and secondary sources.</p>\r\n', 1, 0, '2024-03-08 06:32:01', '2024-03-08 06:32:01', NULL, NULL),
(635, 6, 2, 224, 'Critical Awareness in Historiography', '<p>Develop a critical understanding of developments in historiography, recognizing shifts in historical interpretation and the impact of different historical perspectives.</p>\r\n', 1, 0, '2024-03-08 06:32:45', '2024-03-08 06:32:45', NULL, NULL),
(636, 6, 2, 224, 'Knowledge of Indian History and the 20th Century Modern World', '<p>Acquire comprehensive knowledge of the history of India and the 20th Century Modern World, covering significant events, developments, and their historical contexts.</p>\r\n', 1, 0, '2024-03-08 06:33:26', '2024-03-08 06:33:26', NULL, NULL),
(637, 6, 2, 224, 'Current Debates Awareness', '<p>Stay informed about current historical debates, demonstrating awareness of ongoing discussions and controversies within the field of history.</p>\r\n', 1, 0, '2024-03-08 06:34:39', '2024-03-08 06:34:39', NULL, NULL),
(638, 6, 2, 224, 'Historical Research Skills Understanding', '<p>Understand the skills employed by historians in research, including research design, source analysis, and the application of various methodologies in historical inquiry.</p>\r\n', 1, 0, '2024-03-08 06:35:06', '2024-03-08 06:35:06', NULL, NULL),
