(650, 5, 1, 219, 'Program Outcome', '<ul>\r\n	<li style=\"text-align: justify;\">Graduates will develop strong leadership abilities, enabling them to guide and inspire teams towards achieving organizational goals.</li>\r\n	<li style=\"text-align: justify;\">Students will gain proficiency in making informed and strategic decisions, equipping them to address complex business challenges.</li>\r\n	<li style=\"text-align: justify;\">The program sharpens&nbsp;communication skills, ensuring graduates can convey ideas clearly, and fostering collaboration in diverse professional settings.</li>\r\n	<li style=\"text-align: justify;\">The curriculum instills an understanding of global business trends, preparing students to thrive in an interconnected and dynamic international landscape.</li>\r\n	<li style=\"text-align: justify;\">Emphasis is placed on ethical considerations, enabling graduates to make principled decisions that contribute to responsible and sustainable business practices.</li>\r\n	<li style=\"text-align: justify;\">Students will cultivate effective teamwork skills, learning to collaborate with diverse individuals to achieve collective objectives.</li>\r\n	<li style=\"text-align: justify;\">The program fosters adaptability and innovation, empowering graduates to navigate change and contribute to the development of innovative solutions within organizations.</li>\r\n	<li style=\"text-align: justify;\">Graduates will possess the skills to plan, execute, and oversee projects efficiently, meeting objectives within specified timelines and budgets.</li>\r\n	<li style=\"text-align: justify;\">The curriculum encourages an entrepreneurial mindset, equipping students with the skills and mindset to identify opportunities and drive business innovation.</li>\r\n</ul>\r\n', 1, 0, '2024-03-09 08:20:40', '2024-03-09 08:20:40', NULL, NULL),
(651, 5, 1, 191, 'Program Outcome', '<ul>\r\n	<li>Graduates will develop strong leadership abilities, enabling them to guide and inspire teams towards achieving organizational goals.</li>\r\n	<li>Students will gain proficiency in making informed and strategic decisions, equipping them to address complex business challenges.</li>\r\n	<li>The program hones communication skills, ensuring graduates can convey ideas clearly, and fostering collaboration in diverse professional settings.</li>\r\n	<li>The curriculum instills an understanding of global business trends, preparing students to thrive in an interconnected and dynamic international landscape.</li>\r\n	<li>Emphasis is placed on ethical considerations, enabling graduates to make principled decisions that contribute to responsible and sustainable business practices.</li>\r\n	<li>Students will cultivate effective teamwork skills, learning to collaborate with diverse individuals to achieve collective objectives.</li>\r\n	<li>The program fosters adaptability and innovation, empowering graduates to navigate change and contribute to the development of innovative solutions within organizations.</li>\r\n	<li>Graduates will possess the skills to plan, execute, and oversee projects efficiently, meeting objectives within specified timelines and budgets.</li>\r\n	<li>The curriculum encourages an entrepreneurial mindset, equipping students with the skills and mindset to identify opportunities and drive business innovation.</li>\r\n</ul>\r\n', 1, 0, '2024-03-09 08:23:15', '2024-03-09 08:23:15', NULL, NULL),
