(657, 1, 5, 21, 'PO 1: Engineering Knowledge', '<p><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">Apply the knowledge of mathematics, science, engineering fundamentals and an engineering specialization for the solution of complex engineering problems </span></span></p>\r\n', 1, 0, '2024-03-09 12:31:09', '2024-03-09 12:31:09', NULL, NULL),
(658, 1, 5, 21, 'PO 2: Problem analysis', '<p><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">Identify, formulate, research literature and analyze complex engineering problems reaching substantiated conclusions using first principle of mathematics, natural science and engineering science</span></span></p>\r\n', 1, 0, '2024-03-09 12:31:49', '2024-03-09 12:31:49', NULL, NULL),
(659, 1, 5, 21, 'PO 3: Design / Development of solutions', '<p><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">Design solutions for complex engineering problems and design system components or processes that meet the specified needs with appropriate consideration for public health and safety, and cultural, social and environmental consideration</span></span></p>\r\n', 1, 0, '2024-03-09 12:33:49', '2024-03-09 12:33:49', NULL, NULL),
(660, 1, 5, 21, 'PO 4: Conduct investigation of complex problems', '<p><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">Use research based knowledge and research methods including design of experiments, analysis and interpretation of data, and synthesis of the information to provide valid conclusions</span></span></p>\r\n', 1, 0, '2024-03-09 12:34:46', '2024-03-09 12:34:46', NULL, NULL),
(661, 1, 5, 21, 'PO 5: Modern tool usage', '<p><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">Create, select and apply appropriate techniques and modern engineering and IT tools including prediction and modelling to complex engineering activities with an understanding of the limitations</span></span></p>\r\n', 1, 0, '2024-03-09 12:35:34', '2024-03-09 12:35:34', NULL, NULL),
(662, 1, 5, 21, 'PO 6: The Engineer &amp; Society', '<p><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">Apply reasoning informed by the contextual knowledge to assess societal health, safety and legal and cultural issues and the consequent responsibilities relevant to the professional engineering practice</span></span></p>\r\n', 1, 0, '2024-03-09 12:36:22', '2024-03-09 12:36:22', NULL, NULL),
(663, 1, 5, 21, 'PO 7: Environmental &amp; Sustainability', '<p><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">Understand the impact of the professional engineering solutions in societal and environmental contexts, and demonstrate the knowledge of, and the need for sustainable development</span></span></p>\r\n', 1, 0, '2024-03-09 12:37:31', '2024-03-09 12:37:31', NULL, NULL),
(664, 1, 5, 21, 'PO 8: Ethics', '<p><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">Apply ethical principles and commit to professional ethics and responsibilities and norms of the engineering practice</span></span></p>\r\n', 1, 0, '2024-03-09 12:38:12', '2024-03-09 12:38:12', NULL, NULL),
(665, 1, 5, 21, 'PO 9: Individual &amp; teamwork', '<p><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">Function effectively as an individual, and as a member of leader in diverse terms, and in multidisciplinary settings</span></span></p>\r\n', 1, 0, '2024-03-09 12:39:54', '2024-03-09 12:39:54', NULL, NULL),
(666, 1, 5, 21, 'PO 10: Communication', '<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:18px\">Communicate effectively on complex engineering activities with the engineering community and society at large by comprehending and writing effective reports and design documentation, making effective presentations, and giving and receiving clear instructions.</span></span></p>\r\n', 1, 0, '2024-03-09 12:40:36', '2024-03-09 12:40:36', NULL, NULL),
(667, 1, 5, 21, 'PO 11: Project Management &amp; Finance', '<p><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">Demonstrate knowledge and understanding of the engineering and management principles and apply these to one&rsquo;s work, as a number and leader in term, to manage projects and in multidisciplinary environments</span></span></p>\r\n', 1, 0, '2024-03-09 12:41:08', '2024-03-09 12:41:08', NULL, NULL),
(668, 1, 5, 21, 'PO 12: Life-long learning', '<p><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">Recognize the need for, and have the preparation and ability to engage in independent and life-long learning in the broadest context of technological change.</span></span></p>\r\n', 1, 0, '2024-03-09 12:41:45', '2024-03-09 12:41:45', NULL, NULL),
