(819, 1, 5, 575, 'Engineering Knowledge', '<p>Apply knowledge of mathematics, science, engineering fundamentals, and an engineering specialization to the solution of complex engineering problems.</p>\r\n', 1, 0, '2025-06-11 09:12:53', '2025-06-11 09:12:53', NULL, NULL),
(820, 1, 1, 3, 'PO12: Life-Long Learning', '<p>Recognize the need for, and have the preparation and ability to engage in independent and life-long learning in the broadest context of technological change.</p>\r\n', 1, 0, '2025-10-17 09:54:57', '2025-10-17 09:54:57', NULL, NULL),
(821, 1, 1, 562, 'Problem analysis', '<hr />\r\n<p>Identify, formulate, review research literature, and analyze complex engineering problems reaching substantiated conclusions using first principles of mathematics, natural sciences, and engineering sciences</p>\r\n', 1, 0, '2025-11-11 06:12:02', '2025-11-11 06:12:02', NULL, NULL),
(822, 1, 1, 562, 'Design/development of solutions', '<p>Design solutions for complex engineering problems and design system components or processes that meet the specified needs with appropriate consideration for the public health and safety, and the cultural, societal, and environmental considerations</p>\r\n', 1, 0, '2025-11-11 06:15:24', '2025-11-11 06:15:24', NULL, NULL),
(823, 1, 1, 562, 'Conduct investigations of complex problems', '<p>Use research-based knowledge and research methods including design of experiments, analysis and interpretation of data, and synthesis of the information to provide valid conclusions.</p>\r\n', 1, 0, '2025-11-11 06:15:52', '2025-11-11 06:15:52', NULL, NULL),
(824, 1, 1, 562, 'Modern tool usage', '<p>Create, select, and apply appropriate techniques, resources, and modern engineering and IT tools including prediction and modeling to complex engineering activities with an understanding of the limitations.</p>\r\n', 1, 0, '2025-11-11 06:16:21', '2025-11-11 06:16:21', NULL, NULL),
(825, 1, 1, 562, 'The engineer and society', '<p>Apply reasoning informed by the contextual knowledge to assess societal, health, safety, legal and cultural issues and the consequent responsibilities relevant to the professional engineering practice.</p>\r\n', 1, 0, '2025-11-11 06:16:51', '2025-11-11 06:16:51', NULL, NULL),
(826, 1, 1, 562, 'Environment And Sustainability', '<p>Understand the impact of the professional engineering solutions in societal and environmental contexts, and demonstrate the knowledge of, and need for sustainable development.</p>\r\n', 1, 0, '2025-11-11 06:18:06', '2025-11-11 06:18:06', NULL, NULL),
(827, 1, 1, 562, 'Ethics', '<p>Apply ethical principles and commit to professional ethics and responsibilities and norms of the engineering practice.</p>\r\n', 1, 0, '2025-11-11 06:18:37', '2025-11-11 06:18:37', NULL, NULL),
(828, 1, 1, 562, 'Individual and team work', '<p>function effectively as an individual, and as a member or leader in diverse teams, and in multidisciplinary settings.</p>\r\n', 1, 0, '2025-11-11 06:19:02', '2025-11-11 06:19:02', NULL, NULL),
(829, 1, 1, 562, 'Communication', '<p>Communicate effectively on complex engineering activities with the engineering community and with society at large, such as, being able to comprehend and write effective reports and design documentation, make effective presentations, and give and receive clear instructions.</p>\r\n', 1, 0, '2025-11-11 06:19:29', '2025-11-11 06:19:29', NULL, NULL),
(830, 1, 1, 562, 'Project management and finance', '<p>Demonstrate knowledge and understanding of the engineering andmanagement principles andapply these toone&acirc;&euro;&tilde;s own work, as a member and leader in a team, to manage projects and in multidisciplinary environments</p>\r\n', 1, 0, '2025-11-11 06:19:54', '2025-11-11 06:19:54', NULL, NULL),
(831, 1, 1, 562, 'Life-long learning', '<p>Recognize the need for, and have the preparation and ability to engage in independent and life-long learning in the broadest context of technological change.</p>\r\n', 1, 0, '2025-11-11 06:20:19', '2025-11-11 06:20:19', NULL, NULL),
(832, 1, 1, 562, 'Engineering Knowledge', '<p>Apply knowledge of mathematics, science, engineering fundamentals, and an engineering specialization to the solution of complex engineering problems.</p>\r\n', 1, 0, '2025-11-11 06:20:45', '2025-11-11 06:20:45', NULL, NULL),
(833, 1, 1, 1, 'Program Specific Outcome (PSO) 1', '<p style=\"text-align:left\"><span style=\"font-size:18px\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"color:black\">Applying knowledge of mathematics, science, and engineering fundamentals to civil engineering problems.</span></span></span></p>\r\n', 1, 0, '2025-11-21 07:03:39', '2025-11-21 07:03:39', NULL, NULL),
(834, 1, 1, 1, 'Program Specific Outcome (PSO) 2', '<p style=\"text-align:left\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:18px\"><span style=\"color:black\">The program will provide knowledge and skills for analysis, design, estimation,drawings, software tools and environmental consciousness in the areas of civil engineering.</span></span></span></p>\r\n', 1, 0, '2025-11-21 09:32:23', '2025-11-21 09:32:23', NULL, NULL),
(835, 1, 1, 1, 'Program Specific Outcome (PSO) 3', '<p style=\"text-align:left\"><span style=\"font-size:18px\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"color:black\">Applying appropriate technologies and tools, including prediction and modeling, in civil engineering activities.</span></span></span></p>\r\n', 1, 0, '2025-11-21 09:34:57', '2025-11-21 09:34:57', NULL, NULL),
(836, 1, 1, 1, 'Program Specific Outcome (PSO) 4', '<p style=\"text-align:left\"><span style=\"font-size:18px\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"color:black\">Using research methods to investigate complex problems and synthesize information.</span></span></span></p>\r\n', 1, 0, '2025-11-21 09:37:55', '2025-11-21 09:37:55', NULL, NULL),
(837, 1, 5, 21, 'Program Specific Outcome (PSO) 1', '<p style=\"text-align:left\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:18px\"><span style=\"color:black\">Applying knowledge of mathematics, science, and engineering fundamentals to civil engineering problems.</span></span></span></p>\r\n', 1, 0, '2025-11-21 09:43:35', '2025-11-21 09:43:35', NULL, NULL),
(838, 1, 5, 21, 'Program Specific Outcome (PSO) 2', '<p style=\"text-align:left\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:18px\"><span style=\"color:black\">The program will provide knowledge and skills for analysis, design, estimation,drawings, software tools and environmental consciousness in the areas of civil engineering.</span></span></span></p>\r\n', 1, 0, '2025-11-21 09:45:06', '2025-11-21 09:45:06', NULL, NULL),
(839, 1, 5, 21, 'Program Specific Outcome (PSO) 3', '<p style=\"text-align:left\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:18px\"><span style=\"color:black\">Applying appropriate technologies and tools, including prediction and modeling, in civil engineering activities.</span></span></span></p>\r\n', 1, 0, '2025-11-21 09:45:52', '2025-11-21 09:45:52', NULL, NULL),
(840, 1, 5, 21, 'Program Specific Outcome (PSO) 4', '<p style=\"text-align:left\"><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:18px\"><span style=\"color:black\">Using research methods to investigate complex problems and synthesize information.</span></span></span></p>\r\n', 1, 0, '2025-11-21 09:46:41', '2025-11-21 09:46:41', NULL, NULL),
(841, 26, 1, 365, 'Program Outcome', '<p>Graduates gain a strong foundation in legal principles and the ability to analyze and interpret laws effectively. They develop ethical, research, and communication skills to serve as responsible legal professionals.</p>\r\n', 1, 0, '2025-11-27 09:12:22', '2025-11-27 09:12:22', NULL, NULL),
(842, 4, 1, 54, 'PO 1: Integrated Business Knowledge', '<p><span style=\"font-size:11.0pt\">Demonstrate a comprehensive understanding of accounting, finance, marketing, economics, and management principles,<br />\r\nand apply this knowledge in practical business scenarios.</span></p>\r\n', 1, 0, '2025-12-09 02:48:08', '2025-12-09 02:48:08', NULL, NULL),
(843, 4, 1, 54, 'PO2: Specialization Expertise', '<p><span style=\"font-size:11.0pt\">Attain in-depth knowledge in the chosen area of specialization (e.g., Accounting, Finance, Marketing, or Human Resources),<br />\r\nenabling analysis and strategic decision-making in that field</span></p>\r\n', 1, 0, '2025-12-09 03:17:48', '2025-12-09 03:17:48', NULL, NULL),
(844, 4, 1, 54, 'PO3: Critical Thinking &amp; Problem-Solving', '<p><span style=\"font-size:11.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Develop critical thinking and problem-solving skills to identify, analyze, and address business problems effectively and make informed decisions</span></span></p>\r\n', 1, 0, '2025-12-09 03:19:52', '2025-12-09 03:19:52', NULL, NULL),
(845, 4, 1, 54, 'PO4: Business Communication Skills', '<p><span style=\"font-size:11.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Exhibit effective verbal and written communication skills appropriate to a business environment, including report writing,<br />\r\npresentations, and interpersonal communication.</span></span></p>\r\n', 1, 0, '2025-12-09 03:21:56', '2025-12-09 03:21:56', NULL, NULL),
(846, 4, 1, 54, 'PO5: Ethics &amp; Corporate Responsibility', '<p><span style=\"font-size:11.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Understand ethical issues in business, corporate governance, and social responsibility, and apply ethical reasoning to business practices.</span></span></p>\r\n', 1, 0, '2025-12-09 03:22:45', '2025-12-09 03:22:45', NULL, NULL),
(847, 4, 1, 54, 'PO6: Quantitative &amp; Analytical Skills', '<p><span style=\"font-size:11.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Apply quantitative and analytical skills to interpret business data, perform financial analysis, and support decision-making.</span></span></p>\r\n', 1, 0, '2025-12-09 03:23:28', '2025-12-09 03:23:28', NULL, NULL),
(848, 4, 1, 54, 'PO7: IT &amp; Digital Proficiency', '<p><span style=\"font-size:11.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Use information technology and software tools to enhance productivity, manage information, and support decision-making in a business context.</span></span></p>\r\n', 1, 0, '2025-12-09 03:24:46', '2025-12-09 03:24:46', NULL, NULL),
(849, 4, 1, 54, 'PO8: Teamwork &amp; Leadership', '<p><span style=\"font-size:11.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Develop the ability to work effectively in teams, demonstrate leadership skills, and contribute to the achievement of group objectives.</span></span></p>\r\n', 1, 0, '2025-12-09 03:25:39', '2025-12-09 03:25:39', NULL, NULL),
(850, 4, 1, 54, 'PO9: Global Business Understanding', '<p><span style=\"font-size:11.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Understand the impact of the global environment on business operations, including international trade, cultural diversity, and global financial markets.</span></span></p>\r\n', 1, 0, '2025-12-09 03:26:29', '2025-12-09 03:26:29', NULL, NULL),
(851, 4, 1, 54, 'PO10: Lifelong Learning &amp; Adaptability', '<p><span style=\"font-size:11.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Cultivate a mindset of lifelong learning to adapt to changing business environments and continue professional development in response to new opportunities and challenges.</span></span></p>\r\n', 1, 0, '2025-12-09 03:27:19', '2025-12-09 03:27:19', NULL, NULL),
