(871, 4, 1, 55, 'PO10: Lifelong Learning &amp; Adaptability', '<p><span style=\"font-size:11.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Cultivate a mindset of lifelong learning to adapt to changing business environments and continue professional development in response to new opportunities and challenges.</span></span></p>\r\n', 1, 0, '2025-12-09 03:49:02', '2025-12-09 03:49:02', NULL, NULL),
(872, 4, 2, 56, 'PO1: Advanced Financial Knowledge', '<p><span style=\"font-size:11.0pt\"><span style=\"font-family:&quot;Arial&quot;,sans-serif\">Demonstrate comprehensive knowledge of advanced financial concepts, including financial management, corporate finance, investment analysis, and risk management</span></span></p>\r\n', 1, 0, '2025-12-09 03:51:51', '2025-12-09 03:51:51', NULL, NULL),
(873, 4, 2, 56, 'PO2: Financial Regulation &amp; Compliance', '<p><span style=\"font-size:11.0pt\"><span style=\"font-family:&quot;Arial&quot;,sans-serif\">Understand the regulatory frameworks governing financial markets and institutions, including compliance with accounting standards, taxation, and financial reporting regulations.</span></span></p>\r\n', 1, 0, '2025-12-09 04:00:21', '2025-12-09 04:00:21', NULL, NULL),
(874, 4, 2, 56, 'PO3: Cost Accounting Application', '<p><span style=\"font-size:11.0pt\"><span style=\"font-family:&quot;Arial&quot;,sans-serif\">Apply cost accounting techniques to determine product costs, manage budgets, and control business operations, contributing to the financial efficiency of organizations.</span></span></p>\r\n', 1, 0, '2025-12-09 04:00:59', '2025-12-09 04:00:59', NULL, NULL),
(875, 4, 2, 56, 'PO4: Internal Control &amp; Auditing Skills', '<p><span style=\"font-size:11.0pt\"><span style=\"font-family:&quot;Arial&quot;,sans-serif\">Evaluate and implement effective internal control systems and audit processes to ensure the accuracy, completeness, and compliance of financial records.</span></span></p>\r\n', 1, 0, '2025-12-09 04:02:07', '2025-12-09 04:02:07', NULL, NULL),
