(882, 1, 5, 565, 'Problem Analysis', '<p>Identify, formulate, review research literature, and analyze complex engineering problems reaching substantiated conclusions using first principles of mathematics, natural sciences, and engineering sciences.</p>\r\n', 1, 0, '2025-12-24 06:23:46', '2025-12-24 06:23:46', NULL, NULL),
(883, 1, 5, 565, 'Design/development of solutions', '<p>Design solutions for complex engineering problems and design system components or processes that meet the specified needs with appropriate consideration for the public health and safety, and the cultural, societal, and environmental considerations.</p>\r\n', 1, 0, '2025-12-24 06:24:41', '2025-12-24 06:24:41', NULL, NULL),
(884, 1, 5, 565, 'Conduct investigations of complex problems', '<p>Use research-based knowledge and research methods including design of experiments, analysis and interpretation of data, and synthesis of the information to provide valid conclusions.</p>\r\n', 1, 0, '2025-12-24 06:25:13', '2025-12-24 06:25:13', NULL, NULL),
(885, 1, 5, 565, 'Modern tool usage', '<p>Create, select, and apply appropriate techniques, resources, and modern engineering and IT tools including prediction and modeling to complex engineering activities with an understanding of the limitations.</p>\r\n', 1, 0, '2025-12-24 06:25:46', '2025-12-24 06:25:46', NULL, NULL),
(886, 1, 5, 565, 'The engineer and society', '<p>Apply reasoning informed by the contextual knowledge to assess societal, health, safety, legal and cultural issues and the consequent responsibilities relevant to the professional engineering practice.</p>\r\n', 1, 0, '2025-12-24 06:26:17', '2025-12-24 06:26:17', NULL, NULL),
(887, 1, 5, 565, 'Environment And Sustainability', '<p>Understand the impact of the professional engineering solutions in societal and environmental contexts, and demonstrate the knowledge of, and need for sustainable development.</p>\r\n', 1, 0, '2025-12-24 06:26:48', '2025-12-24 06:26:48', NULL, NULL),
(888, 1, 5, 565, 'Ethics', '<p>Apply ethical principles and commit to professional ethics and responsibilities and norms of the engineering practice.</p>\r\n', 1, 0, '2025-12-24 06:29:12', '2025-12-24 06:29:12', NULL, NULL),
(889, 1, 5, 565, 'Individual and team work', '<p>function effectively as an individual, and as a member or leader in diverse teams, and in multidisciplinary settings.</p>\r\n', 1, 0, '2025-12-24 06:29:42', '2025-12-24 06:29:42', NULL, NULL),
(890, 1, 5, 565, 'Communication', '<p>Communicate effectively on complex engineering activities with the engineering community and with society at large, such as, being able to comprehend and write effective reports and design documentation, make effective presentations, and give and receive clear instructions.</p>\r\n', 1, 0, '2025-12-24 06:30:15', '2025-12-24 06:30:15', NULL, NULL),
(891, 1, 5, 565, 'Project management and finance', '<p>Demonstrate knowledge and understanding of the engineering andmanagement principles andapply these toone&acirc;&euro;&tilde;s own work, as a member and leader in a team, to manage projects and in multidisciplinary environments</p>\r\n', 1, 0, '2025-12-24 06:30:48', '2025-12-24 06:30:48', NULL, NULL),
(892, 1, 5, 565, 'Life-long learning', '<p>Recognize the need for, and have the preparation and ability to engage in independent and life-long learning in the broadest context of technological change.</p>\r\n', 1, 0, '2025-12-24 06:31:15', '2025-12-24 06:31:15', NULL, NULL),
(893, 1, 5, 565, 'Engineering Knowledge', '<p>Apply knowledge of mathematics, science, engineering fundamentals, and an engineering specialization to the solution of complex engineering problems</p>\r\n', 1, 0, '2025-12-24 06:31:51', '2025-12-24 06:31:51', NULL, NULL);
