(2047, 4, NULL, NULL, '69', 'Dr Chirag Vyas', 'cvvyas@gmiu.edu.in', '8799128371', 'CVV', 'Head of Department', '2023-06-01', 'GF-38', '15 years', '<p style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#727272\">Dr. Chirag Vyas is working as Associate Professor and HOD - at the Faculty of Management Gyanmanjari Innovative University (GMIU). Prior to Joining GMIU, He was working as an Assistant Professor in the Faculty of Management CHARUSAT University, Changa. He has also worked as Hired Research Consultant for the School of Liberal Studies (SLS), Pandit Deendayal Petroleum University (PDPU), Gandhinagar in a Major Research project which was funded by the Indian Council of Social Science Research (ICSSR), New Delhi. Project Number: IMPRESS/P2019/41/18-19/ICSSR. Project Domain: Media, Culture, and Society. Project Director: Dr. Ashish B. Joshi. Project Amount Sanctioned: INR.10,00,000. He has published 4 Books out of which 3 were published by International Publishers. His 12 papers were published in UGC &ndash; CARE Listed Journals. 1 Paper Published in SCOPUS Indexed Journal. He has served as session chair in 3 International conferences which were Organized outside India one of which was sponsored by Emerald Publishing. He is also associated with ICAI and CED as Consulting Trainer Since 2008. He has presented 34 Papers (12 International, 22 National) in Conferences / Seminars. He is also working as project Director for </span></span></span><span style=\"font-size:10.5pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#333333\"><span style=\"background-color:#ffffff\">Special Call for Short-term Empirical Research 2023-24 </span></span></span></span><span style=\"font-size:11pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#727272\">a Major Research project which is funded by the Indian Council of Social Science Research (ICSSR), New Delhi. Project Number: </span></span></span><span style=\"font-size:9pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\"><strong>F.No. </strong></span></span></span><span style=\"font-size:9pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\"><strong><em>277</em></strong></span></span></span><span style=\"font-size:9pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\"><strong>/CRP-2023-667</strong></span></span></span><span style=\"font-size:9pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\">/</span></span></span><span style=\"font-size:9pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\"><strong>NEP20/SCD</strong></span></span></span><span style=\"font-size:11pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#727272\">. Project Domain: NEP. Project Director: </span></span></span><span style=\"font-size:11pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\"><strong>Dr. Vilas Kulkarni</strong></span></span></span><span style=\"font-size:11pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#727272\">. Project Amount Sanctioned: INR. 12,00,000.</span></span></span></p>\r\n', '2024-03-09-74-CVV.png', 'gmiu@123?', NULL, 0, 1, '2024-03-09 16:07:06', '2024-10-26 02:54:00', NULL, NULL),
(2048, 4, NULL, NULL, '69', 'Prof. Ratna Vyas', 'rvvyas@gmiu.edu.in', '7574949494', 'RVV', 'Assistant Professor', '2023-06-01', 'SF-21', '10+ Years', '<p style=\"text-align:justify\"><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\">Prof. Ratna V&nbsp; Vyas is an Assistant Professor in the Faculty of Management Studies at Gyanmanjari Innovative University, bringing a wealth of knowledge, dedication, and passion to our esteemed institution.</span></span></span><span style=\"font-size:8pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#727272\"><span style=\"background-color:#ffffff\"> </span></span></span></span><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\"><strong>Ratna Vyas</strong></span></span></span><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\"> is working as </span></span></span><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\"><strong>Assistant Professor</strong></span></span></span><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\"> - at the Faculty of Management at Gyanmanjari Innovative University </span></span></span><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\"><strong>(GMIU). </strong></span></span></span><span style=\"font-size:10pt\"><span style=\"font-family:Arial,sans-serif\"><span style=\"color:#000000\">Prior to Joining GMIU, She was working as an Assistant Professor in the Faculty of Management CHARUSAT University, Changa. She is pursuing her Ph.D. at Sardar Patel University, Vallabh Vidyanagar.&nbsp; She is also associated with ICAI and CED as Consulting Trainer.&nbsp;</span></span></span></p>\r\n\r\n<p>&nbsp;</p>\r\n', '2024-03-09-10-RVV.png', 'gmiu@123?', NULL, 0, 1, '2024-03-09 16:36:00', '2024-10-26 02:54:16', NULL, NULL),
(2049, 4, NULL, NULL, '53,54,55,56,57,58,60,63,64,66,67,68,69,70,73,74,75,76,77,78,79,80,81,82,83,84,127,191,192,193,205,219,220,221,297,298,299,300,310,365,588,616', 'Dr Chirag Vyas', 'cvvyas@gmiu.edu.in', '9537793363', 'CVV', 'Director ( Management, Commerce &amp; Liberal Studies )', '2025-02-03', 'SF-43', '15 years', '<p style=\"text-align:justify\">Dr. Chirag Vyas&nbsp;is working as&nbsp;Director&nbsp;(Management, Commerce and Liberal Studies) in&nbsp;Gyanmanjari Innovative University (GMIU).&nbsp;Prior to Joining GMIU, He was working as an Assistant Professor in the Faculty of Management CHARUSAT University, Changa. He has also worked as Hired Research Consultant for the School of Liberal Studies (SLS), Pandit Deendayal Petroleum University (PDPU), Gandhinagar in a Major Research project which was funded by the Indian Council of Social Science Research (ICSSR), New Delhi. Project Number: IMPRESS/P2019/41/18-19/ICSSR. Project Domain: Media, Culture, and Society. Project Director: Dr. Ashish B. Joshi. Project Amount Sanctioned: INR.10,00,000. He has Completed one more research project funded by ICSSR in association with Prof (Dr) Vilas Kulkarni - MBA Department - Sardar Patel University, Vallabh Vidyanagar and Rs. 12,00,000 Sanctioned for this research project. He has published 3 Books out of which 2 were published by International Publishers and 1 National. His 12 papers were published in UGC &ndash; CARE Listed Journals. 1 Paper Published in SCOPUS Indexed Journal. He has served as session chair in 3 International conferences which were Organized outside India one of which was sponsored by Emerald Publishing. He is also associated with ICAI and CED as Consulting Trainer Since 2008. He has presented 37&nbsp;Papers in International and National Conferences / Seminars.</p>\r\n\r\n<p>&nbsp;</p>\r\n', '2025-08-07-41-1000694311 (1).jpg', 'gmiu@123?', NULL, 1, 0, '2024-03-09 16:56:01', '2025-11-12 06:09:58', NULL, NULL);
