(2457, 4, NULL, NULL, '4,5,25,30,33,126,233,245,257,562,563,565,575,604,606,607,608,613,620', 'Prof. Het N. Pandya', 'hnpandya@gmiu.edu.in', '0', 'HNP', 'ASSISTANT PROFESSOR', '2024-12-30', 'FF-38', '1 Years', '<p>&nbsp;I am an M.Tech graduate from Nirma university, Ahmedabad with a strong skills in Remote Sensing, Python programming and Machine learning. Passionate about Research and development,</p>\r\n', '2025-03-12-46-WhatsApp Image 2025-03-12 at 1.36.02 PM.jpeg', NULL, NULL, 1, 0, '2025-03-12 06:39:49', '2025-11-10 07:25:08', NULL, NULL),
(2458, 4, NULL, NULL, '4,5,13,25,29,30,33,232,233,565,575,605,607,608,613,620', 'Prof.Karan S.Makwana', 'ksmakwana@gmiu.edu.in', '6355009392', 'KSM', 'ASSISTANT PROFESSOR', '2025-01-27', 'FF-38', '0 Years', '<p>Java, Python, C++, MongoDB, Express JS, React JS, Node JS, MySQL, Machine Learning.</p>\r\n', '2025-07-23-28-karansir.jpg', NULL, NULL, 1, 0, '2025-03-12 08:18:45', '2025-12-24 08:19:25', NULL, NULL),
