(2460, 4, NULL, NULL, '4,5,25,29,30,33,232,233,257,562,563,565,575,605,606,607,608,620', 'Prof.Pragnesh H. Kanejiya', 'phkanejiya@gmiu.edu.in', '840178290', 'PHK', 'ASSISTANT PROFESSOR', '2025-12-03', 'FF-31', '1 Years', '<p>Flutter development,Android Development,Data stucture,HTML,CSS,IOT</p>\r\n', '2025-03-12-46-WhatsApp Image 2025-03-12 at 2.15.16 PM.jpeg', NULL, NULL, 1, 0, '2025-03-12 08:32:55', '2025-11-10 07:34:51', NULL, NULL),
(2461, 4, NULL, NULL, NULL, 'Prof. Vandna J.Makwana', 'vjmakwana@gmiu.edu.in', '0', 'VJM', 'ASSISTANT PROFESSOR', '2024-07-01', 'FF-37', '8 Years', '<h3><strong>Quality Engineer &amp; Educator</strong></h3>\r\n\r\n<p>With over&nbsp;<strong>9 years of diverse experience</strong>&nbsp;in the&nbsp;<strong>industry</strong>&nbsp;and as an educator in the&nbsp;<strong>teaching sector</strong>, I am passionate about enhancing software quality and imparting knowledge to the next generation of tech enthusiasts.</p>\r\n\r\n<p>My teaching role allows me to share my real-world industry experience with students, providing them with valuable insights into the world of&nbsp;<strong>quality assurance</strong>,&nbsp;<strong>software testing</strong>, and&nbsp;<strong>software engineering practices</strong>.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>I am also constantly learning new technologies and methodologies to stay updated with the latest trends, ensuring that I can pass on the most relevant and up-to-date knowledge to my students.</p>\r\n\r\n<p>As an educator, I am dedicated to fostering new learning skills, mentoring students, and helping them grow into successful professionals in the tech world.</p>\r\n', '2025-03-12-92-VJM.jpg', NULL, NULL, 1, 0, '2025-03-12 08:57:08', '2025-07-22 07:08:38', NULL, NULL),
(2462, 4, NULL, NULL, '89,90', 'Prof.Hitesh S.Rathod', 'hsrathod@gmiu.edu.in', '9106636722', 'HSR', 'ASSISTANT PROFESSOR', '2024-06-07', 'FF-24', '3 Years', '<p>web designing&nbsp;</p>\r\n', '2025-03-12-27-IMG_20250312_140904300.jpg', NULL, NULL, 1, 0, '2025-03-12 09:19:31', '2025-12-30 07:42:34', NULL, NULL),
