(2543, 4, NULL, NULL, '3,16,24,212,213,239,244,252,256,259', 'Jahnvi Mistry', 'jmmistry@gmiu.edu.in', '9428971782', 'JMM', 'Lecturer', '2025-09-17', 'GF-37', '0.5', '<p>I have completed my MSc in Physics with a specialization in Astronomy and Astrophysics.&nbsp;</p>\r\n', '2025-09-27-93-20230617_145223-COLLAGE~2 - Jahnvi Mistry.jpg', NULL, NULL, 1, 0, '2025-07-22 16:40:03', '2025-12-14 09:51:19', NULL, NULL),
(2544, 4, NULL, NULL, '40,49', 'Prof. Urvi G. Parajiya', 'ugparajiya@gmiu.edu.in', '9106940803', 'UGP', 'Teaching Assistant', '2022-08-22', 'SF- 44', '3 years', '<p>I am M.Sc (Microbiology) graduate from Department of Lifesciences, Maharaja Krishnakumarsinhji Bhavnagar University, Bhavnagar with an expertise in Environmental Microbiology, Molecular Biology and Bioprocess Engenieering.&nbsp;</p>\r\n', '2025-07-23-63-1000003891__01.jpg', NULL, NULL, 1, 0, '2025-07-23 03:57:55', '2025-07-25 10:19:05', NULL, NULL),
